function StarRow({ rating, size = 14, color = GOLD }) {
  const full = Math.floor(rating);
  const half = rating - full >= 0.5;
  return (
    <div style={{ display: "flex", gap: 2 }}>
      {[0, 1, 2, 3, 4].map((i) => {
        const filled = i < full || (i === full && half);
        return (
          <Star key={i} size={size} fill={filled ? color : "none"} color={filled ? color : "#E3D3BC"} strokeWidth={1.5} />
        );
      })}
    </div>
  );
}

function LogoBrilho({ width, style, src = LOGO_B64, alt = "Babá de Aluguel" }) {
  return (
    <div style={{ position: "relative", width, overflow: "hidden", display: "inline-block", ...style }}>
      <img src={src} alt={alt} style={{ width: "100%", display: "block" }} />
      <div style={{
        position: "absolute", top: 0, left: "-160%", width: "45%", height: "100%",
        background: "linear-gradient(115deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0) 35%, rgba(255,255,255,0.9) 50%, rgba(255,255,255,0) 65%, rgba(255,255,255,0) 100%)",
        transform: "skewX(-18deg)",
        animation: "logo-shine-sweep 3.2s ease-in-out infinite",
        pointerEvents: "none",
      }} />
    </div>
  );
}

function Avatar({ initials, color, size = 44, fotoUrl }) {
  if (fotoUrl) {
    return (
      <img
        src={fotoUrl}
        alt=""
        style={{
          width: size, height: size, borderRadius: "50%", objectFit: "cover",
          border: "2px solid " + CARD, boxShadow: "0 2px 6px rgba(22,64,60,0.18)", flexShrink: 0,
        }}
      />
    );
  }
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%", background: color,
      display: "flex", alignItems: "center", justifyContent: "center",
      color: PAPER, fontFamily: "Fraunces, serif", fontWeight: 600, fontSize: size * 0.36,
      flexShrink: 0, border: "2px solid " + CARD, boxShadow: "0 2px 6px rgba(22,64,60,0.18)",
    }}>
      {initials}
    </div>
  );
}

function Breakdown({ breakdown }) {
  const total = Object.values(breakdown).reduce((a, b) => a + b, 0) || 1;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
      {[5, 4, 3, 2, 1].map((n) => {
        const pct = Math.round((breakdown[n] / total) * 100);
        return (
          <div key={n} style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ fontSize: 12, width: 10, color: INK }}>{n}</span>
            <Star size={11} fill={GOLD} color={GOLD} />
            <div style={{ flex: 1, height: 6, background: "#FBEBD9", borderRadius: 4, overflow: "hidden" }}>
              <div style={{ width: `${pct}%`, height: "100%", background: WINE, borderRadius: 4 }} />
            </div>
            <span style={{ fontSize: 11, width: 26, color: INK_SOFT, textAlign: "right" }}>{breakdown[n]}</span>
          </div>
        );
      })}
    </div>
  );
}

function Tabs({ tabs, active, onChange }) {
  return (
    <div style={{ display: "flex", borderBottom: `1px solid ${LINE}`, marginTop: 18 }}>
      {tabs.map((t) => (
        <button key={t} onClick={() => onChange(t)} style={{
          flex: 1, background: "none", border: "none", cursor: "pointer",
          padding: "10px 4px", fontFamily: "Manrope, sans-serif", fontSize: 12.5,
          color: active === t ? INK : "#8B6A52",
          borderBottom: active === t ? `2px solid ${GOLD}` : "2px solid transparent",
          fontWeight: active === t ? 700 : 500,
        }}>
          {t}
        </button>
      ))}
    </div>
  );
}

