function MaeView({ onSelect, perfilImpulsionado, boosts, bloqueados = [] }) {
  const [search, setSearch] = useState("");
  const [bairro, setBairro] = useState("Todos");
  const [ratingMin, setRatingMin] = useState(0);
  const [preco, setPreco] = useState([15, 45]);
  const [filtrosAbertos, setFiltrosAbertos] = useState(false);
  const [popupAberto, setPopupAberto] = useState(!!boosts?.popup?.ativo);
  const bairros = ["Todos", ...new Set(babas.map((b) => b.bairro))];
  const filtrosAtivos = ratingMin > 0 || preco[0] > 15 || preco[1] < 45;

  const filtradas = useMemo(() => {
    const resultado = babas.filter((b) => {
      if (bloqueados.includes(b.id)) return false;
      const matchNome = b.name.toLowerCase().includes(search.toLowerCase());
      const matchBairro = bairro === "Todos" || b.bairro === bairro;
      const matchRating = b.rating >= ratingMin;
      const matchPreco = b.valorCombinar || (b.precoHora >= preco[0] && b.precoHora <= preco[1]);
      return matchNome && matchBairro && matchRating && matchPreco;
    });
    if (boosts?.destaque?.ativo && perfilImpulsionado) {
      return [{ ...perfilImpulsionado, destaque: true }, ...resultado.filter((b) => b.id !== perfilImpulsionado.id)];
    }
    return resultado;
  }, [search, bairro, ratingMin, preco, boosts, perfilImpulsionado, bloqueados]);

  return (
    <div style={{ display: "flex", height: "100%", position: "relative" }}>
      <div style={{ flex: 1, minWidth: 0, overflowY: "auto", padding: "16px 14px 20px 16px", fontFamily: "Manrope, sans-serif" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, background: CARD, border: `1px solid ${LINE}`, borderRadius: 12, padding: "10px 13px", marginBottom: 12 }}>
          <Search size={15} color="#8B6A52" />
          <input
            value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar por nome"
            style={{ border: "none", outline: "none", fontSize: 13, flex: 1, fontFamily: "Manrope, sans-serif", background: "transparent", color: INK }}
          />
        </div>

        {boosts?.banner?.ativo && perfilImpulsionado && (
          <BannerPatrocinado baba={perfilImpulsionado} onSelect={onSelect} />
        )}

        <div style={{ display: "flex", gap: 6, marginBottom: 14, overflowX: "auto" }}>
          {bairros.map((b) => (
            <button key={b} onClick={() => setBairro(b)} style={{
              whiteSpace: "nowrap", fontSize: 11.5, padding: "6px 13px", borderRadius: 20,
              border: `1px solid ${bairro === b ? INK : LINE}`,
              background: bairro === b ? INK : "transparent",
              color: bairro === b ? PAPER : INK_SOFT, cursor: "pointer",
            }}>
              {b}
            </button>
          ))}
        </div>

        <p style={{ fontSize: 11.5, color: "#8B6A52", marginBottom: 10 }}>
          {filtradas.length} {filtradas.length === 1 ? "babá encontrada" : "babás encontradas"}
        </p>

        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {filtradas.map((b) => <BabaCard key={b.id} baba={b} destaque={b.destaque} onClick={() => onSelect(b)} />)}
          {filtradas.length === 0 && (
            <p style={{ textAlign: "center", color: "#8B6A52", fontSize: 12.5, marginTop: 20 }}>
              Nenhuma babá encontrada com esses filtros.
            </p>
          )}
        </div>
      </div>

      {filtrosAbertos ? (
        <VerticalFilterBar ratingMin={ratingMin} setRatingMin={setRatingMin} preco={preco} setPreco={setPreco}
          onReset={() => { setRatingMin(0); setPreco([15, 45]); }} onFechar={() => setFiltrosAbertos(false)} />
      ) : (
        <FilterTab onClick={() => setFiltrosAbertos(true)} filtrosAtivos={filtrosAtivos} />
      )}

      {popupAberto && boosts?.popup?.ativo && perfilImpulsionado && (
        <PopupPatrocinado baba={perfilImpulsionado} onSelect={onSelect} onClose={() => setPopupAberto(false)} />
      )}
    </div>
  );
}

