function DiaristaDetail({
  diarista, onBack, editable, onAtualizarFoto, onSalvarPerfil, onAdicionarTrabalho, onAgendar, avaliacoesExtras = [],
  onVerAgenda, pendentesCount = 0, onDenunciar, onBloquear, meuContato, onConfigurarContato, onAvisoSilencioso,
}) {
  const [tab, setTab] = useState("Sobre");
  const [showCall, setShowCall] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [showAgendar, setShowAgendar] = useState(false);
  const [showFotoModal, setShowFotoModal] = useState(false);
  const [showTrabalhoModal, setShowTrabalhoModal] = useState(false);
  const [showShare, setShowShare] = useState(false);
  const [showDenunciar, setShowDenunciar] = useState(false);
  const [seguindo, setSeguindo] = useState(false);
  const [seguidores, setSeguidores] = useState(diarista.seguidores || 0);
  const [edit, setEdit] = useState(null);
  const [testeEnviado, setTesteEnviado] = useState(false);

  const extras = avaliacoesExtras.filter((a) => a.prestadorId === diarista.id);
  const ratingCount = diarista.ratingCount + extras.length;
  const rating = ratingCount > 0 ? (diarista.rating * diarista.ratingCount + extras.reduce((s, a) => s + a.estrelas, 0)) / ratingCount : 0;
  const breakdown = { ...diarista.breakdown };
  extras.forEach((a) => { breakdown[a.estrelas] = (breakdown[a.estrelas] || 0) + 1; });
  const depoimentos = [
    ...extras.filter((a) => a.comentario).map((a) => ({ author: a.autor || "Cliente", relacao: "avaliação recente", texto: a.comentario })),
    ...diarista.depoimentos,
  ];
  const tabs = ["Sobre", "Trabalhos", "Depoimentos", "Avaliações", "Valores & agenda"];
  const editando = edit !== null;

  const iniciarEdicao = () => {
    setEdit({
      name: diarista.name,
      bairro: diarista.bairro,
      idade: String(diarista.idade),
      valorCombinar: diarista.valorCombinar,
      valorFaxina: diarista.precoHora != null ? String(diarista.precoHora) : "",
      valorGeladeira: extrairValorPacote(diarista.servicos, "Limpar geladeira"),
      valorLoucas: extrairValorPacote(diarista.servicos, "Lavar louça"),
      valorPassarRoupa: extrairValorPacote(diarista.servicos, "Passar roupa"),
      valorComida: extrairValorPacote(diarista.servicos, "Fazer comida"),
      valorPosObraEvento: extrairValorPacote(diarista.servicos, "Limpeza pós-obra ou pós-evento"),
      agenda: { ...diarista.agenda },
      contatosConfianca: diarista.contatosConfianca || [],
    });
  };

  const alternarDia = (dia) => {
    setEdit((e) => ({
      ...e,
      agenda: { ...e.agenda, [dia]: e.agenda[dia] === "Indisponível" ? "A combinar" : "Indisponível" },
    }));
  };

  const setCampoEdit = (chave, valor) => setEdit((e) => ({ ...e, [chave]: valor }));

  const salvarEdicao = () => {
    const precoHora = edit.valorCombinar ? null : (edit.valorFaxina ? Number(edit.valorFaxina) : null);
    const servicos = edit.valorCombinar
      ? [{ label: "Faxina", valor: "A combinar" }]
      : [
          ...(precoHora != null ? [{ label: "Faxina completa (diária)", valor: `R$ ${precoHora}` }] : []),
          ...(edit.valorGeladeira ? [{ label: "Limpar geladeira", valor: `R$ ${edit.valorGeladeira}` }] : []),
          ...(edit.valorLoucas ? [{ label: "Lavar louça", valor: `R$ ${edit.valorLoucas}` }] : []),
          ...(edit.valorPassarRoupa ? [{ label: "Passar roupa", valor: `R$ ${edit.valorPassarRoupa}` }] : []),
          ...(edit.valorComida ? [{ label: "Fazer comida", valor: `R$ ${edit.valorComida}` }] : []),
          ...(edit.valorPosObraEvento ? [{ label: "Limpeza pós-obra ou pós-evento", valor: `R$ ${edit.valorPosObraEvento}` }] : []),
        ];
    const contatosValidos = (edit.contatosConfianca || []).filter((c) => c.nome.trim() && c.telefone.trim());
    onSalvarPerfil?.({
      name: edit.name.trim() || diarista.name,
      bairro: edit.bairro.trim() || diarista.bairro,
      idade: Number(edit.idade) || diarista.idade,
      valorCombinar: edit.valorCombinar,
      precoHora,
      servicos,
      agenda: edit.agenda,
      contatosConfianca: edit.contatosConfianca || [],
    });
    setEdit(null);
    if (contatosValidos.length > 0) {
      setTesteEnviado(true);
      setTimeout(() => setTesteEnviado(false), 4000);
    }
  };

  return (
    <div style={{ position: "relative", height: "100%", display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "16px 16px", background: "#5A2420" }}>
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer" }}>
          <ChevronLeft size={20} color="#FFF6F1" />
        </button>
        <span style={{ color: "#FFF6F1", fontFamily: "Manrope, sans-serif", fontSize: 13.5, flex: 1 }}>
          {editable ? "Meu perfil" : "Perfil da diarista"}
        </span>
        {editable && onVerAgenda && !editando && (
          <button onClick={onVerAgenda} title="Minha agenda" style={{
            position: "relative", display: "flex", alignItems: "center", justifyContent: "center", width: 28, height: 28,
            borderRadius: "50%", background: "rgba(226,122,109,0.22)", border: `1px solid ${D_CORAL}`, cursor: "pointer",
          }}>
            <CalendarClock size={13} color={D_CORAL} />
            {pendentesCount > 0 && (
              <span style={{
                position: "absolute", top: -3, right: -3, minWidth: 15, height: 15, borderRadius: 8,
                background: "#D64545", color: "#FFFFFF", fontSize: 9, fontWeight: 700,
                display: "flex", alignItems: "center", justifyContent: "center", padding: "0 3px",
              }}>
                {pendentesCount}
              </span>
            )}
          </button>
        )}
        {!editable && (onDenunciar || onBloquear) && (
          <button onClick={() => setShowDenunciar(true)} title="Denunciar ou bloquear" style={{
            display: "flex", alignItems: "center", justifyContent: "center", width: 28, height: 28,
            borderRadius: "50%", background: "rgba(226,122,109,0.22)", border: `1px solid ${D_CORAL}`, cursor: "pointer",
          }}>
            <MoreVertical size={13} color={D_CORAL} />
          </button>
        )}
        <button onClick={() => setShowShare(true)} title="Compartilhar perfil" style={{
          display: "flex", alignItems: "center", justifyContent: "center", width: 28, height: 28,
          borderRadius: "50%", background: "rgba(226,122,109,0.22)", border: `1px solid ${D_CORAL}`, cursor: "pointer",
        }}>
          <Share2 size={12} color={D_CORAL} />
        </button>
        {editable && !editando && (
          <button onClick={iniciarEdicao} style={{
            display: "flex", alignItems: "center", gap: 5, background: "rgba(226,122,109,0.22)",
            border: `1px solid ${D_CORAL}`, borderRadius: 20, padding: "6px 11px", cursor: "pointer",
          }}>
            <Edit3 size={12} color={D_CORAL} />
            <span style={{ fontSize: 10.5, color: "#FFF6F1", fontFamily: "Manrope, sans-serif" }}>Editar perfil</span>
          </button>
        )}
        {editable && editando && (
          <div style={{ display: "flex", gap: 6 }}>
            <button onClick={() => setEdit(null)} style={{
              background: "none", border: "1px solid #FFF6F1", borderRadius: 20, padding: "6px 11px", cursor: "pointer",
            }}>
              <span style={{ fontSize: 10.5, color: "#FFF6F1", fontFamily: "Manrope, sans-serif" }}>Cancelar</span>
            </button>
            <button onClick={salvarEdicao} style={{
              display: "flex", alignItems: "center", gap: 5, background: D_CORAL,
              border: "none", borderRadius: 20, padding: "6px 11px", cursor: "pointer",
            }}>
              <Check size={12} color="#FFFFFF" />
              <span style={{ fontSize: 10.5, color: "#FFFFFF", fontFamily: "Manrope, sans-serif", fontWeight: 700 }}>Salvar</span>
            </button>
          </div>
        )}
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "20px 18px 146px", background: "#FFF6F1" }}>
        {testeEnviado && (
          <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#E4F1EC", border: `1px solid ${FOREST}`, borderRadius: 12, padding: "10px 13px", marginBottom: 14 }}>
            <CheckCircle2 size={14} color={FOREST} style={{ flexShrink: 0 }} />
            <span style={{ fontSize: 11.5, color: FOREST }}>Mensagem de teste enviada para o(s) seu(s) contato(s) de confiança.</span>
          </div>
        )}
        {editable && diarista.statusPagamento === "pendente" && (
          <div style={{
            display: "flex", alignItems: "flex-start", gap: 9, background: "#F8E3DF",
            border: `1px solid ${D_CORAL_DEEP}`, borderRadius: 12, padding: "11px 13px", marginBottom: 16,
          }}>
            <Clock3 size={15} color={D_CORAL_DEEP} style={{ marginTop: 1, flexShrink: 0 }} />
            <span style={{ fontSize: 11.5, fontFamily: "Manrope, sans-serif", color: "#6B2E24", lineHeight: 1.5 }}>
              Seu perfil está em análise. Assim que o pagamento do boleto for compensado (em até 48h), ele fica visível para os clientes.
            </span>
          </div>
        )}

        {editable && !diarista.fotoUrl && (
          <div style={{
            display: "flex", alignItems: "flex-start", gap: 9, background: "#F8E3DF",
            border: "1px solid #F3D9D5", borderRadius: 12, padding: "11px 13px", marginBottom: 16,
          }}>
            <Camera size={15} color={D_CORAL_DEEP} style={{ marginTop: 1, flexShrink: 0 }} />
            <div style={{ flex: 1 }}>
              <span style={{ fontSize: 11.5, fontFamily: "Manrope, sans-serif", color: "#5A2420", lineHeight: 1.5 }}>
                Falta um passo: adicione sua foto de perfil. Ela só pode ser tirada pela câmera, na hora.
              </span>
              <button onClick={() => setShowFotoModal(true)} style={{
                display: "block", marginTop: 8, background: "none", border: "none", cursor: "pointer",
                color: D_CORAL_DEEP, fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 11.5,
              }}>
                Tirar foto agora
              </button>
            </div>
          </div>
        )}

        <div style={{ display: "flex", gap: 14, alignItems: editando ? "flex-start" : "center" }}>
          <div style={{ position: "relative", flexShrink: 0 }}>
            <Avatar initials={diarista.initials} color={diarista.color} fotoUrl={diarista.fotoUrl} size={66} />
            {editando && diarista.fotoUrl && (
              <button onClick={() => setShowFotoModal(true)} title="Trocar foto" style={{
                position: "absolute", bottom: -2, right: -2, width: 22, height: 22, borderRadius: "50%",
                background: D_CORAL, border: "2px solid #FFF6F1", display: "flex", alignItems: "center",
                justifyContent: "center", cursor: "pointer",
              }}>
                <Camera size={11} color="#FFFFFF" />
              </button>
            )}
          </div>
          {editando ? (
            <div style={{ flex: 1 }}>
              <CampoEdit label="Nome completo">
                <input style={inputStyle} value={edit.name} onChange={(e) => setCampoEdit("name", e.target.value)} />
              </CampoEdit>
              <div style={{ display: "flex", gap: 8 }}>
                <div style={{ flex: 2 }}>
                  <CampoEdit label="Bairro">
                    <input style={inputStyle} value={edit.bairro} onChange={(e) => setCampoEdit("bairro", e.target.value)} />
                  </CampoEdit>
                </div>
                <div style={{ flex: 1 }}>
                  <CampoEdit label="Idade">
                    <input style={inputStyle} type="number" value={edit.idade} onChange={(e) => setCampoEdit("idade", e.target.value)} />
                  </CampoEdit>
                </div>
              </div>
            </div>
          ) : (
            <div>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <span style={{ fontFamily: "Fraunces, serif", fontSize: 20, color: "#5A2420", fontWeight: 600 }}>{diarista.name}</span>
                {diarista.verificada && <ShieldCheck size={16} color={D_CORAL_DEEP} />}
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#8B6A52", fontSize: 12.5, fontFamily: "Manrope, sans-serif" }}>
                <MapPin size={12} /> {diarista.bairro} · {diarista.idade} anos
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 5 }}>
                {ratingCount > 0 ? (
                  <>
                    <StarRow rating={rating} />
                    <span style={{ fontSize: 12.5, fontFamily: "Manrope, sans-serif", color: "#5A2420", fontWeight: 700 }}>{rating.toFixed(1)}</span>
                    <span style={{ fontSize: 12, color: "#8B6A52", fontFamily: "Manrope, sans-serif" }}>({ratingCount} avaliações)</span>
                  </>
                ) : (
                  <span style={{ fontSize: 12, color: "#8B6A52", fontFamily: "Manrope, sans-serif" }}>Ainda sem avaliações</span>
                )}
              </div>
            </div>
          )}
        </div>

        {!editando && (
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 10 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
              <Users size={13} color="#8B6A52" />
              <span style={{ fontSize: 12, color: "#8B6A52", fontFamily: "Manrope, sans-serif" }}>
                <b style={{ color: "#5A2420" }}>{seguidores}</b> seguidores
              </span>
            </div>
            {!editable && (
              <button onClick={() => { setSeguindo((s) => !s); setSeguidores((n) => n + (seguindo ? -1 : 1)); }} style={{
                display: "flex", alignItems: "center", gap: 5, cursor: "pointer", borderRadius: 20, padding: "5px 12px",
                border: `1px solid ${seguindo ? "#F3D9D5" : D_CORAL_DEEP}`,
                background: seguindo ? "transparent" : D_CORAL,
                color: seguindo ? "#8B6A52" : "#FFFFFF",
              }}>
                {seguindo ? <Check size={12} /> : <UserPlus size={12} />}
                <span style={{ fontSize: 11.5, fontFamily: "Manrope, sans-serif", fontWeight: 700 }}>
                  {seguindo ? "Seguindo" : "Seguir"}
                </span>
              </button>
            )}
          </div>
        )}

        <div style={{ display: "flex", gap: 6, marginTop: 14, flexWrap: "wrap" }}>
          {diarista.tags.map((t) => (
            <span key={t} style={{ fontSize: 11, fontFamily: "Manrope, sans-serif", padding: "5px 11px", borderRadius: 20, background: "#F8E3DF", color: "#5A2420" }}>
              {t}
            </span>
          ))}
        </div>

        <Tabs tabs={tabs} active={tab} onChange={setTab} />

        <div style={{ marginTop: 18, fontFamily: "Manrope, sans-serif" }}>
          {tab === "Sobre" && (
            <div>
              <p style={{ fontSize: 13.5, lineHeight: 1.65, color: "#3A2420", marginBottom: 16 }}>{diarista.bio}</p>
              <div style={{ background: "#FFFFFF", border: "1px solid #F3D9D5", borderRadius: 14, padding: "12px 15px" }}>
                <p style={{ fontSize: 12, fontWeight: 700, color: "#5A2420", marginBottom: 4 }}>Características</p>
                <Caracteristica ok={diarista.fazFaxina} label="Faz faxina completa" />
                <Caracteristica ok={diarista.fazComida} label="Faz comida" />
                <Caracteristica ok={diarista.trabalhaComEquipe} label="Trabalha com mais pessoas" />
                <Caracteristica ok={diarista.disponibilidadeNoite} label="Disponibilidade à noite" />
                <Caracteristica ok={diarista.disponibilidadeFimDeSemana} label="Disponibilidade nos fins de semana" />
                <div style={{ borderTop: "1px solid #F3D9D5", margin: "8px 0" }} />
                <InfoRow icon={<Home size={15} color={D_CORAL_DEEP} />} label="Cidade" valor={diarista.cidade || "São Paulo"} />
                <InfoRow icon={<Car size={15} color={D_CORAL_DEEP} />} label="Transporte" valor={diarista.transporte} />
              </div>
            </div>
          )}

          {tab === "Trabalhos" && (
            <div>
              <p style={{ fontSize: 11.5, color: "#8B6A52", marginBottom: 12 }}>
                Fotos de trabalhos já feitos por {diarista.name.split(" ")[0]}. {editable ? "Poste quantas quiser." : ""}
              </p>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                {diarista.trabalhos.map((foto) => (
                  <div key={foto.id} style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                    <div style={{
                      aspectRatio: "1", borderRadius: 12, background: foto.url ? undefined : (foto.cor || D_CORAL_LIGHT),
                      display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden", position: "relative",
                    }}>
                      {foto.url ? (
                        <img src={foto.url} alt={foto.legenda || "Trabalho realizado"} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                      ) : (
                        <Sparkles size={20} color="#FFFFFF" style={{ opacity: 0.85 }} />
                      )}
                      {foto.marcado && (
                        <span style={{
                          position: "absolute", bottom: 5, left: 5, display: "flex", alignItems: "center", gap: 3,
                          background: "rgba(90,36,32,0.72)", color: "#FFFFFF", fontSize: 9, fontWeight: 700,
                          padding: "2px 7px", borderRadius: 10,
                        }}>
                          <Tag size={9} /> {foto.marcado}
                        </span>
                      )}
                    </div>
                    {foto.legenda && (
                      <span style={{ fontSize: 10.5, color: "#5A2420", fontFamily: "Manrope, sans-serif", lineHeight: 1.35 }}>
                        {foto.legenda}
                      </span>
                    )}
                  </div>
                ))}
                {editable && (
                  <button onClick={() => setShowTrabalhoModal(true)} style={{
                    aspectRatio: "1", borderRadius: 12, background: "#FFFFFF", border: `1.5px dashed ${D_CORAL}`,
                    display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
                    gap: 4, cursor: "pointer",
                  }}>
                    <Camera size={16} color={D_CORAL_DEEP} />
                    <span style={{ fontSize: 9.5, color: D_CORAL_DEEP, fontWeight: 700 }}>Adicionar</span>
                  </button>
                )}
              </div>
              {diarista.trabalhos.length === 0 && !editable && (
                <p style={{ fontSize: 12.5, color: "#8B6A52", textAlign: "center", padding: "20px 0" }}>
                  Essa diarista ainda não postou fotos de trabalhos.
                </p>
              )}
            </div>
          )}

          {tab === "Depoimentos" && (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {depoimentos.length === 0 && (
                <p style={{ fontSize: 12.5, color: "#8B6A52", textAlign: "center", padding: "20px 0" }}>
                  {editable ? "Você ainda não recebeu depoimentos." : "Essa diarista ainda não recebeu depoimentos."}
                </p>
              )}
              {depoimentos.map((d, i) => (
                <div key={i} style={{ background: "#FFFFFF", borderRadius: 14, padding: "13px 15px", border: "1px solid #F3D9D5", boxShadow: "0 2px 8px rgba(90,36,32,0.04)" }}>
                  <Quote size={14} color={D_CORAL} />
                  <p style={{ fontSize: 13, lineHeight: 1.6, color: "#3A2420", margin: "7px 0" }}>{d.texto}</p>
                  <p style={{ fontSize: 11.5, color: "#8B6A52" }}>{d.author} — {d.relacao}</p>
                </div>
              ))}
              {editable && (
                <p style={{ fontSize: 11.5, color: "#8B6A52", textAlign: "center" }}>
                  Os depoimentos são enviados pelos clientes após o serviço.
                </p>
              )}
            </div>
          )}

          {tab === "Avaliações" && (
            <div>
              {ratingCount === 0 ? (
                <p style={{ fontSize: 12.5, color: "#8B6A52", textAlign: "center", padding: "20px 0" }}>
                  {editable ? "Você ainda não recebeu avaliações." : "Essa diarista ainda não recebeu avaliações."}
                </p>
              ) : (
                <>
                  <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 18 }}>
                    <span style={{ fontFamily: "Fraunces, serif", fontSize: 36, color: "#5A2420", fontWeight: 600 }}>{rating.toFixed(1)}</span>
                    <div>
                      <StarRow rating={rating} size={16} />
                      <p style={{ fontSize: 11.5, color: "#8B6A52", marginTop: 3 }}>{ratingCount} avaliações no total</p>
                    </div>
                  </div>
                  <Breakdown breakdown={breakdown} />
                </>
              )}
            </div>
          )}

          {tab === "Valores & agenda" && (
            <div>
              <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 9 }}>
                <Wallet size={14} color={D_CORAL_DEEP} />
                <span style={{ fontSize: 12.5, fontWeight: 700, color: "#5A2420" }}>Valores e acréscimos</span>
                {editable && !editando && (
                  <button style={editPillDiarista} onClick={iniciarEdicao}>editar</button>
                )}
              </div>

              {editando ? (
                <div style={{ marginBottom: 20 }}>
                  <ChoicePills
                    options={["Definir valores", "Combinar pelo chat"]}
                    value={edit.valorCombinar ? "Combinar pelo chat" : "Definir valores"}
                    onChange={(v) => setCampoEdit("valorCombinar", v === "Combinar pelo chat")}
                  />
                  {!edit.valorCombinar && (
                    <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 10 }}>
                      <CampoEdit label="Valor da faxina — diária (até R$ 500)">
                        <input style={inputStyle} type="number" min={1} max={500} value={edit.valorFaxina}
                          onChange={(e) => setCampoEdit("valorFaxina", e.target.value > 500 ? "500" : e.target.value)} />
                      </CampoEdit>
                      <CampoEdit label="Acréscimo — limpar geladeira (opcional)">
                        <input style={inputStyle} type="number" min={1} max={150} value={edit.valorGeladeira}
                          onChange={(e) => setCampoEdit("valorGeladeira", e.target.value > 150 ? "150" : e.target.value)} />
                      </CampoEdit>
                      <CampoEdit label="Acréscimo — lavar louça (opcional)">
                        <input style={inputStyle} type="number" min={1} max={150} value={edit.valorLoucas}
                          onChange={(e) => setCampoEdit("valorLoucas", e.target.value > 150 ? "150" : e.target.value)} />
                      </CampoEdit>
                      <CampoEdit label="Acréscimo — passar roupa (opcional)">
                        <input style={inputStyle} type="number" min={1} max={200} value={edit.valorPassarRoupa}
                          onChange={(e) => setCampoEdit("valorPassarRoupa", e.target.value > 200 ? "200" : e.target.value)} />
                      </CampoEdit>
                      <CampoEdit label="Acréscimo — fazer comida (opcional)">
                        <input style={inputStyle} type="number" min={1} max={150} value={edit.valorComida}
                          onChange={(e) => setCampoEdit("valorComida", e.target.value > 150 ? "150" : e.target.value)} />
                      </CampoEdit>
                      <CampoEdit label="Acréscimo — limpeza pós-obra ou pós-evento (opcional)">
                        <input style={inputStyle} type="number" min={1} max={600} value={edit.valorPosObraEvento}
                          onChange={(e) => setCampoEdit("valorPosObraEvento", e.target.value > 600 ? "600" : e.target.value)} />
                      </CampoEdit>
                    </div>
                  )}
                </div>
              ) : diarista.valorCombinar ? (
                <div style={{
                  display: "flex", alignItems: "center", gap: 10, background: "#F8E3DF",
                  borderRadius: 12, padding: "12px 13px", marginBottom: 20,
                }}>
                  <MessageCircle size={16} color={D_CORAL_DEEP} />
                  <span style={{ fontSize: 12.5, color: "#5A2420" }}>
                    {diarista.name.split(" ")[0]} prefere combinar os valores diretamente pelo chat, conforme o serviço.
                  </span>
                </div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 7, marginBottom: 20 }}>
                  {diarista.servicos.map((s) => (
                    <div key={s.label} style={{ display: "flex", justifyContent: "space-between", fontSize: 13, padding: "10px 13px", background: "#FFFFFF", borderRadius: 12, border: "1px solid #F3D9D5" }}>
                      <span style={{ color: "#3A2420" }}>{s.label}</span>
                      <span style={{ color: "#5A2420", fontWeight: 700 }}>{s.valor}</span>
                    </div>
                  ))}
                </div>
              )}

              <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 9 }}>
                <Calendar size={14} color={D_CORAL_DEEP} />
                <span style={{ fontSize: 12.5, fontWeight: 700, color: "#5A2420" }}>Agenda semanal</span>
                {editable && !editando && (
                  <button style={editPillDiarista} onClick={iniciarEdicao}>editar</button>
                )}
              </div>
              {editando ? (
                <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
                  {Object.entries(edit.agenda).map(([dia, horario]) => (
                    <button key={dia} onClick={() => alternarDia(dia)} style={{
                      display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 12.5,
                      padding: "8px 10px", borderRadius: 10, cursor: "pointer", width: "100%",
                      border: `1px solid ${horario === "Indisponível" ? "#F3D9D5" : D_CORAL_DEEP}`,
                      background: horario === "Indisponível" ? "transparent" : "#F8E3DF",
                    }}>
                      <span style={{ color: "#3A2420", fontWeight: 700 }}>{dia}</span>
                      <span style={{ color: horario === "Indisponível" ? "#8B6A52" : D_CORAL_DEEP, display: "flex", alignItems: "center", gap: 4 }}>
                        {horario !== "Indisponível" && <Clock size={11} />} {horario}
                      </span>
                    </button>
                  ))}
                  <p style={{ fontSize: 10.5, color: "#8B6A52", marginTop: 4 }}>Toque em um dia para alternar entre disponível e indisponível.</p>
                </div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
                  {Object.entries(diarista.agenda).map(([dia, horario]) => (
                    <div key={dia} style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, padding: "7px 3px" }}>
                      <span style={{ color: "#3A2420", width: 40 }}>{dia}</span>
                      <span style={{ color: horario === "Indisponível" ? "#C7A9A2" : "#5A2420", display: "flex", alignItems: "center", gap: 4 }}>
                        {horario !== "Indisponível" && <Clock size={11} />} {horario}
                      </span>
                    </div>
                  ))}
                </div>
              )}

              {editable && (
                <div style={{ marginTop: 18 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 9 }}>
                    <Siren size={13} color={ERROR} />
                    <span style={{ fontSize: 12.5, fontWeight: 700, color: "#3A2420" }}>Contatos de confiança (emergência)</span>
                    {!editando && <button style={editPillDiarista} onClick={iniciarEdicao}>editar</button>}
                  </div>
                  {editando ? (
                    <ContatoConfiancaEditor
                      contatos={edit.contatosConfianca}
                      onChange={(novos) => setCampoEdit("contatosConfianca", novos)}
                      corDestaque={ERROR}
                    />
                  ) : (
                    <ContatosConfiancaView contatos={diarista.contatosConfianca} />
                  )}
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {!editable && (
        <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, padding: 16, display: "flex", flexDirection: "column", gap: 8, background: "linear-gradient(180deg, transparent, #FFF6F1 30%)" }}>
          <button onClick={() => setShowAgendar(true)} style={{
            display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
            background: "transparent", border: `1.5px solid ${D_CORAL_DEEP}`, borderRadius: 12,
            padding: "12px 16px", fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 13.5,
            cursor: "pointer", color: D_CORAL_DEEP, width: "100%",
          }}>
            <CalendarCheck size={16} /> Agendar com {diarista.name.split(" ")[0]}
          </button>
          <button className="shine-cta" style={{
            display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
            background: `linear-gradient(120deg, ${D_CORAL_LIGHT} 0%, ${D_CORAL} 55%, ${D_CORAL_DEEP} 100%)`,
            color: "#FFFFFF", border: "none", borderRadius: 12,
            padding: "13px 16px", fontFamily: "Manrope, sans-serif", fontWeight: 700,
            fontSize: 14, cursor: "pointer", boxShadow: "0 4px 14px rgba(201,68,48,0.35)", width: "100%",
          }} onClick={() => setShowCall(true)}>
            <MessageCircle size={16} /> Chamar {diarista.name.split(" ")[0]} no particular
          </button>
        </div>
      )}

      {showCall && (
        <CallModal
          baba={diarista}
          onClose={() => setShowCall(false)}
          onAbrirChat={() => { setShowCall(false); setShowChat(true); }}
        />
      )}
      {showChat && (
        <ChatScreen
          nome={diarista.name} iniciais={diarista.initials} cor={diarista.color} fotoUrl={diarista.fotoUrl}
          corDestaque={D_CORAL_DEEP} onClose={() => setShowChat(false)}
          meuContato={meuContato} onConfigurarContato={onConfigurarContato} onAvisoSilencioso={onAvisoSilencioso}
        />
      )}
      {showFotoModal && (
        <FotoModal
          onClose={() => setShowFotoModal(false)}
          onSalvar={(foto) => {
            onAtualizarFoto?.(foto);
            setShowFotoModal(false);
          }}
        />
      )}
      {showTrabalhoModal && (
        <TrabalhoModal
          onClose={() => setShowTrabalhoModal(false)}
          onSalvar={(trabalho) => {
            onAdicionarTrabalho?.(trabalho);
            setShowTrabalhoModal(false);
          }}
        />
      )}
      {showShare && <ShareModal nome={diarista.name} appNome="diarista" corDestaque={D_CORAL_DEEP} onClose={() => setShowShare(false)} />}
      {showAgendar && (
        <AgendarModal
          prestador={diarista}
          tipoServico="Faxina"
          corDestaque={D_CORAL_DEEP}
          onClose={() => setShowAgendar(false)}
          onConfirmar={(dados) => onAgendar?.(diarista, "diarista", dados)}
        />
      )}
      {showDenunciar && (
        <DenunciarBloquearModal
          nome={diarista.name}
          corDestaque={D_CORAL_DEEP}
          onClose={() => setShowDenunciar(false)}
          onBloquear={() => onBloquear?.(diarista)}
          onDenunciar={(motivo, detalhes) => onDenunciar?.(diarista, motivo, detalhes)}
        />
      )}
    </div>
  );
}

const editPillDiarista = {
  marginLeft: "auto", fontSize: 10.5, fontFamily: "Manrope, sans-serif",
  background: "none", border: `1px solid ${D_CORAL_DEEP}`, color: D_CORAL_DEEP,
  borderRadius: 20, padding: "3px 10px", cursor: "pointer",
};

function NotificacoesScreen({ notificacoes, onVoltar, onLerTodas }) {
  return (
    <div style={{ position: "absolute", inset: 0, background: PAPER, zIndex: 32, display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "16px 16px", background: INK }}>
        <button onClick={onVoltar} style={{ background: "none", border: "none", cursor: "pointer" }}>
          <ChevronLeft size={20} color={PAPER} />
        </button>
        <span style={{ color: PAPER, fontFamily: "Manrope, sans-serif", fontSize: 13.5, flex: 1 }}>Notificações</span>
        {notificacoes.some((n) => !n.lida) && (
          <button onClick={onLerTodas} style={{ background: "none", border: "none", color: GOLD, fontSize: 10.5, cursor: "pointer", fontFamily: "Manrope, sans-serif" }}>
            Marcar todas como lidas
          </button>
        )}
      </div>
      <div style={{ flex: 1, overflowY: "auto", padding: "6px 16px", fontFamily: "Manrope, sans-serif" }}>
        {notificacoes.length === 0 && (
          <p style={{ textAlign: "center", color: "#8B6A52", marginTop: 40, fontSize: 12.5 }}>Nenhuma notificação por aqui.</p>
        )}
        {notificacoes.map((n) => (
          <div key={n.id} style={{ display: "flex", gap: 10, padding: "13px 4px", borderBottom: `1px solid ${LINE}`, opacity: n.lida ? 0.6 : 1 }}>
            <Bell size={15} color={GOLD_DEEP} style={{ marginTop: 2, flexShrink: 0 }} />
            <p style={{ fontSize: 12.5, color: INK, margin: 0, lineHeight: 1.5, flex: 1 }}>{n.texto}</p>
            {!n.lida && <span style={{ width: 7, height: 7, borderRadius: "50%", background: GOLD_DEEP, flexShrink: 0, marginTop: 5 }} />}
          </div>
        ))}
      </div>
    </div>
  );
}

function StatusBadge({ status }) {
  const cores = {
    pendente: { bg: "#FFF3D6", cor: "#8A6A16", label: "Aguardando confirmação" },
    agendado: { bg: "#FBEBD9", cor: GOLD_DEEP, label: "Agendado" },
    concluido: { bg: "#E4F1EC", cor: FOREST, label: "Concluído" },
    cancelado: { bg: "#F6E3E1", cor: ERROR, label: "Cancelado" },
    recusado: { bg: "#F6E3E1", cor: ERROR, label: "Recusado" },
  };
  const c = cores[status] || cores.agendado;
  return (
    <span style={{ fontSize: 10, fontWeight: 700, color: c.cor, background: c.bg, padding: "3px 9px", borderRadius: 10 }}>
      {c.label}
    </span>
  );
}

function CheckinModal({ contratacao, papel, meuContato, onConfirmarOk, onPedirAjuda, onClose, onAvisoAutomatico, corDestaque = "#C23B3B" }) {
  const contatos = meuContato?.contatosConfianca || [];
  const [restante, setRestante] = useState(contatos.length > 0 ? 10 : 0);
  const [avisado, setAvisado] = useState(false);
  const outroNome = papel === "cliente" ? contratacao.prestadorNome.split(" ")[0] : contratacao.clienteNome.split(" ")[0];

  useEffect(() => {
    if (restante <= 0) {
      if (contatos.length > 0 && !avisado) {
        setAvisado(true);
        onAvisoAutomatico?.(contatos, `Não recebemos confirmação após o atendimento com ${outroNome} (${contratacao.data} às ${contratacao.horario}). Por favor, tente falar comigo.`);
      }
      return;
    }
    const t = setTimeout(() => setRestante((r) => r - 1), 1000);
    return () => clearTimeout(t);
  }, [restante, avisado]);

  return (
    <div style={{ position: "absolute", inset: 0, background: "rgba(22,64,60,0.6)", display: "flex", alignItems: "flex-end", zIndex: 45 }}>
      <div style={{
        background: CARD, width: "100%", borderRadius: "22px 22px 0 0",
        padding: "22px 20px 28px", fontFamily: "Manrope, sans-serif", boxSizing: "border-box",
      }}>
        <p style={{ fontFamily: "Fraunces, serif", fontSize: 17, color: INK, marginBottom: 8 }}>
          Correu tudo bem com {outroNome}?
        </p>
        <p style={{ fontSize: 12, color: INK_SOFT, marginBottom: 16, lineHeight: 1.5 }}>
          {contratacao.servico} — {contratacao.data} às {contratacao.horario}
        </p>

        {!avisado && contatos.length > 0 && (
          <p style={{ fontSize: 11, color: "#8A6A16", marginBottom: 14 }}>
            Se você não responder, avisaremos {contatos[0].nome} em {restante}s.
          </p>
        )}
        {avisado && (
          <div style={{ display: "flex", alignItems: "flex-start", gap: 7, background: "#FBEBD9", borderRadius: 10, padding: "9px 12px", marginBottom: 14 }}>
            <ShieldAlert size={13} color={GOLD_DEEP} style={{ flexShrink: 0, marginTop: 1 }} />
            <span style={{ fontSize: 11, color: "#6B4A24" }}>Avisamos {contatos.map((c) => c.nome).join(", ")} por segurança. Você ainda pode responder abaixo.</span>
          </div>
        )}

        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <button onClick={onConfirmarOk} style={{ ...btnPrimary, background: FOREST, width: "100%" }}>
            <CheckCircle2 size={16} /> Sim, tudo certo
          </button>
          <button onClick={onPedirAjuda} style={{ ...btnSecondary, width: "100%", border: `1.5px solid ${corDestaque}`, color: corDestaque }}>
            <Siren size={16} /> Preciso de ajuda
          </button>
          <button onClick={onClose} style={{ background: "none", border: "none", color: "#8B6A52", fontSize: 11.5, cursor: "pointer", marginTop: 2 }}>
            Responder mais tarde
          </button>
        </div>
      </div>
    </div>
  );
}

function HistoricoItem({
  c, papel, ehPrestador, onAceitar, onRecusar, onCheckin, onCheckout, onConcluir, onCancelar,
  onEmergencia, onIniciarCheckin, onAvaliar, onAvisoContato, meuContato, corDestaque,
}) {
  return (
    <div style={{ background: CARD, border: `1px solid ${LINE}`, borderRadius: 14, padding: "13px 14px", marginBottom: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 6 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <Avatar initials={c.prestadorIniciais} color={c.prestadorCor} fotoUrl={c.prestadorFoto} size={34} />
          <div>
            <p style={{ fontSize: 13, fontWeight: 700, color: INK, margin: 0 }}>
              {papel === "cliente" ? c.prestadorNome : c.clienteNome}
            </p>
            <p style={{ fontSize: 10.5, color: "#8B6A52", margin: 0 }}>{c.servico}</p>
          </div>
        </div>
        <StatusBadge status={c.status} />
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, color: INK_SOFT, marginBottom: c.status !== "cancelado" ? 8 : 0 }}>
        <span style={{ display: "flex", alignItems: "center", gap: 4 }}><CalendarClock size={12} /> {c.data} às {c.horario}</span>
        <span style={{ fontWeight: 700, color: INK }}>{c.valor}</span>
      </div>

      {ehPrestador && c.status === "pendente" && (
        <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
          <button onClick={() => onRecusar(c.id)} style={{
            flex: 1, fontSize: 11, fontWeight: 700, padding: "7px 0", borderRadius: 9, cursor: "pointer",
            border: `1px solid ${ERROR}`, background: "none", color: ERROR,
          }}>
            Recusar
          </button>
          <button onClick={() => onAceitar(c.id)} style={{
            flex: 1, fontSize: 11, fontWeight: 700, padding: "7px 0", borderRadius: 9, cursor: "pointer",
            border: "none", background: FOREST, color: "#FFFFFF",
          }}>
            Aceitar
          </button>
        </div>
      )}
      {!ehPrestador && c.status === "pendente" && (
        <p style={{ fontSize: 10.5, color: "#8A6A16", display: "flex", alignItems: "center", gap: 4, margin: "4px 0 0" }}>
          <Clock3 size={11} /> Aguardando {c.prestadorNome.split(" ")[0]} confirmar
        </p>
      )}

      {ehPrestador && c.status === "agendado" && (
        <div style={{ display: "flex", gap: 8, marginTop: 4, marginBottom: (c.checkin || c.checkout) ? 6 : 0 }}>
          {!c.checkin && (
            <button onClick={() => onCheckin(c.id)} style={{
              flex: 1, fontSize: 11, fontWeight: 700, padding: "7px 0", borderRadius: 9, cursor: "pointer",
              border: `1px solid ${GOLD_DEEP}`, background: "none", color: GOLD_DEEP,
            }}>
              Cheguei
            </button>
          )}
          {c.checkin && !c.checkout && (
            <button onClick={() => onCheckout(c.id)} style={{
              flex: 1, fontSize: 11, fontWeight: 700, padding: "7px 0", borderRadius: 9, cursor: "pointer",
              border: `1px solid ${GOLD_DEEP}`, background: "none", color: GOLD_DEEP,
            }}>
              Saí
            </button>
          )}
        </div>
      )}
      {(c.checkin || c.checkout) && (
        <p style={{ fontSize: 10, color: "#8B6A52", margin: "0 0 6px" }}>
          {c.checkin && `Chegou às ${c.checkin}`}{c.checkin && c.checkout ? " · " : ""}{c.checkout && `Saiu às ${c.checkout}`}
        </p>
      )}
      {c.status === "agendado" && (
        <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
          <button onClick={() => (ehPrestador ? onConcluir(c.id) : onIniciarCheckin(c))} style={{
            flex: 1, fontSize: 11, fontWeight: 700, padding: "7px 0", borderRadius: 9, cursor: "pointer",
            border: `1px solid ${FOREST}`, background: "none", color: FOREST,
          }}>
            Marcar como concluído
          </button>
          {!ehPrestador && (
            <button onClick={() => onCancelar(c.id)} style={{
              flex: 1, fontSize: 11, fontWeight: 700, padding: "7px 0", borderRadius: 9, cursor: "pointer",
              border: `1px solid ${ERROR}`, background: "none", color: ERROR,
            }}>
              Cancelar
            </button>
          )}
          {!ehPrestador && (
            <button onClick={() => onEmergencia(c)} title="Emergência" style={{
              width: 34, flexShrink: 0, fontSize: 11, fontWeight: 700, borderRadius: 9, cursor: "pointer",
              border: `1px solid ${ERROR}`, background: "none", color: ERROR, display: "flex",
              alignItems: "center", justifyContent: "center",
            }}>
              <Siren size={14} />
            </button>
          )}
        </div>
      )}
      {c.status === "agendado" && meuContato?.contatosConfianca?.length > 0 && (
        <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 6 }}>
          <AvisoSilenciosoButton
            meuContato={meuContato}
            contexto={`${c.servico} com ${papel === "cliente" ? c.prestadorNome : c.clienteNome}`}
            onAcionar={onAvisoContato}
          />
        </div>
      )}
      {papel === "cliente" && c.status === "concluido" && !c.avaliado && (
        <button onClick={() => onAvaliar(c)} style={{
          width: "100%", fontSize: 11, fontWeight: 700, padding: "8px 0", borderRadius: 9, cursor: "pointer",
          border: "none", background: corDestaque, color: "#FFFFFF", marginTop: 4,
        }}>
          Avaliar
        </button>
      )}
      {papel === "cliente" && c.status === "concluido" && c.avaliado && (
        <p style={{ fontSize: 10.5, color: FOREST, display: "flex", alignItems: "center", gap: 4, margin: "4px 0 0" }}>
          <CheckCircle2 size={11} /> Você já avaliou
        </p>
      )}
      {c.status === "recusado" && (
        <p style={{ fontSize: 10.5, color: ERROR, display: "flex", alignItems: "center", gap: 4, margin: "4px 0 0" }}>
          <XCircle size={11} /> {ehPrestador ? "Você recusou este pedido" : "Não foi possível confirmar esse horário. Tente outra babá ou horário."}
        </p>
      )}
    </div>
  );
}

function HistoricoScreen({
  contratacoes, papel, onVoltar, onAvaliar, onConcluir, onCancelar, onAceitar, onRecusar,
  onCheckin, onCheckout, onAvisoContato,
  corDestaque = GOLD_DEEP, corHeader = INK, corTexto = PAPER, meuContato = null,
}) {
  const ehPrestador = papel !== "cliente";
  const [emergenciaCtx, setEmergenciaCtx] = useState(null);
  const [checkinAlvo, setCheckinAlvo] = useState(null);
  const pendentes = contratacoes.filter((c) => c.status === "pendente");
  const proximos = contratacoes.filter((c) => c.status === "agendado");
  const passados = contratacoes.filter((c) => c.status !== "agendado" && c.status !== "pendente");

  const itemProps = {
    papel, ehPrestador, onAceitar, onRecusar, onCheckin, onCheckout, onConcluir, onCancelar,
    onEmergencia: setEmergenciaCtx, onIniciarCheckin: setCheckinAlvo, onAvaliar, onAvisoContato, meuContato, corDestaque,
  };

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "16px 16px", background: corHeader }}>
        <button onClick={onVoltar} style={{ background: "none", border: "none", cursor: "pointer" }}>
          <ChevronLeft size={20} color={corTexto} />
        </button>
        <span style={{ color: corTexto, fontFamily: "Manrope, sans-serif", fontSize: 13.5 }}>
          {papel === "cliente" ? "Minhas contratações" : "Minha agenda de trabalhos"}
        </span>
      </div>
      <div style={{ flex: 1, overflowY: "auto", padding: "18px 16px", fontFamily: "Manrope, sans-serif" }}>
        {contratacoes.length === 0 && (
          <div style={{ textAlign: "center", padding: "40px 10px" }}>
            <ClipboardList size={28} color="#C7B8A3" style={{ marginBottom: 10 }} />
            <p style={{ fontSize: 12.5, color: "#8B6A52" }}>
              {papel === "cliente" ? "Você ainda não agendou nenhum serviço." : "Você ainda não tem nenhum trabalho agendado."}
            </p>
          </div>
        )}
        {pendentes.length > 0 && (
          <>
            <p style={{ fontSize: 11, fontWeight: 700, color: "#8A6A16", marginBottom: 8 }}>
              {ehPrestador ? "AGUARDANDO SUA CONFIRMAÇÃO" : "AGUARDANDO CONFIRMAÇÃO"}
            </p>
            {pendentes.map((c) => <HistoricoItem key={c.id} c={c} {...itemProps} />)}
          </>
        )}
        {proximos.length > 0 && (
          <>
            <p style={{ fontSize: 11, fontWeight: 700, color: "#8B6A52", marginBottom: 8 }}>PRÓXIMOS</p>
            {proximos.map((c) => <HistoricoItem key={c.id} c={c} {...itemProps} />)}
          </>
        )}
        {passados.length > 0 && (
          <>
            <p style={{ fontSize: 11, fontWeight: 700, color: "#8B6A52", margin: "14px 0 8px" }}>ANTERIORES</p>
            {passados.map((c) => <HistoricoItem key={c.id} c={c} {...itemProps} />)}
          </>
        )}
      </div>
      {emergenciaCtx && (
        <EmergenciaModal
          nome={papel === "cliente" ? emergenciaCtx.prestadorNome : emergenciaCtx.clienteNome}
          contexto={`${emergenciaCtx.servico} — ${emergenciaCtx.data} às ${emergenciaCtx.horario}`}
          meuContato={meuContato}
          onAvisar={onAvisoContato}
          corDestaque={ERROR}
          onClose={() => setEmergenciaCtx(null)}
        />
      )}
      {checkinAlvo && (
        <CheckinModal
          contratacao={checkinAlvo}
          papel={papel}
          meuContato={meuContato}
          onAvisoAutomatico={onAvisoContato}
          onConfirmarOk={() => { onConcluir(checkinAlvo.id); setCheckinAlvo(null); }}
          onPedirAjuda={() => { setEmergenciaCtx(checkinAlvo); setCheckinAlvo(null); }}
          onClose={() => setCheckinAlvo(null)}
          corDestaque={ERROR}
        />
      )}
    </div>
  );
}

function ContatoConfiancaEditor({ contatos, onChange, corDestaque = "#C23B3B" }) {
  const lista = contatos && contatos.length > 0 ? contatos : [];

  const atualizar = (idx, campo, valor) => {
    onChange(lista.map((c, i) => (i === idx ? { ...c, [campo]: valor } : c)));
  };
  const adicionar = () => {
    if (lista.length >= 3) return;
    const novoId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    onChange([...lista, { id: novoId, nome: "", telefone: "", relacao: "" }]);
  };
  const remover = (idx) => onChange(lista.filter((_, i) => i !== idx));

  return (
    <div>
      {lista.map((c, idx) => (
        <div key={c.id || idx} style={{ background: "#FBEBD9", border: `1px solid ${LINE}`, borderRadius: 12, padding: "10px 12px 2px", marginBottom: 8 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
            <span style={{ fontSize: 10, fontWeight: 700, color: "#8B6A52" }}>
              {idx === 0 ? "CONTATO PRINCIPAL" : `CONTATO ${idx + 1}`}
            </span>
            <button onClick={() => remover(idx)} title="Remover" style={{ background: "none", border: "none", cursor: "pointer", color: ERROR, padding: 2 }}>
              <X size={13} />
            </button>
          </div>
          <CampoEdit label="Nome">
            <input style={inputStyle} value={c.nome} onChange={(e) => atualizar(idx, "nome", e.target.value)} placeholder="Ex: sua irmã, uma amiga" />
          </CampoEdit>
          <div style={{ display: "flex", gap: 8 }}>
            <div style={{ flex: 3 }}>
              <CampoEdit label="Telefone">
                <input style={inputStyle} value={c.telefone} onChange={(e) => atualizar(idx, "telefone", e.target.value)} placeholder="(11) 90000-0000" />
              </CampoEdit>
            </div>
            <div style={{ flex: 2 }}>
              <CampoEdit label="Relação">
                <input style={inputStyle} value={c.relacao} onChange={(e) => atualizar(idx, "relacao", e.target.value)} placeholder="Irmã, amiga..." />
              </CampoEdit>
            </div>
          </div>
        </div>
      ))}
      {lista.length < 3 && (
        <button onClick={adicionar} style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6, width: "100%",
          background: "none", border: `1.5px dashed ${corDestaque}`, borderRadius: 10, padding: "9px 12px",
          cursor: "pointer", color: corDestaque, fontSize: 12, fontWeight: 700, fontFamily: "Manrope, sans-serif",
        }}>
          <UserPlus size={13} /> Adicionar contato{lista.length > 0 ? ` (${lista.length}/3)` : ""}
        </button>
      )}
    </div>
  );
}

function ContatosConfiancaView({ contatos }) {
  if (!contatos || contatos.length === 0) {
    return <p style={{ fontSize: 13, color: "#8B6A52", margin: 0 }}>Não configurado</p>;
  }
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 3 }}>
      {contatos.map((c, idx) => (
        <p key={c.id || idx} style={{ fontSize: 13, color: INK, margin: 0 }}>
          {c.nome || "Sem nome"}{c.relacao ? ` (${c.relacao})` : ""} — {c.telefone || "sem telefone"}
          {idx === 0 && contatos.length > 1 && <span style={{ color: "#8B6A52", fontSize: 10.5 }}> · principal</span>}
        </p>
      ))}
    </div>
  );
}

function EmergenciaModal({ nome, contexto, meuContato, onClose, onConfigurarContato, onAvisar, corDestaque = "#C23B3B" }) {
  const [enviado, setEnviado] = useState(false);
  const [compartilhandoLocal, setCompartilhandoLocal] = useState(false);
  const [segundosLocal, setSegundosLocal] = useState(0);
  const contatos = meuContato?.contatosConfianca || [];
  const nomesContatos = contatos.map((c) => c.nome).filter(Boolean).join(", ");

  useEffect(() => {
    if (!compartilhandoLocal) return;
    const t = setInterval(() => setSegundosLocal((s) => s + 1), 1000);
    return () => clearInterval(t);
  }, [compartilhandoLocal]);

  const horaAgora = () => new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
  const mensagem = contexto
    ? `Estou em atendimento com ${nome} (${contexto}). Caso não tenha notícias minhas em breve, entre em contato comigo.`
    : `Estou em contato com ${nome} agora pelo app. Caso não tenha notícias minhas em breve, entre em contato comigo.`;
  const formatarTempo = (s) => `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

  return (
    <div style={{ position: "absolute", inset: 0, background: "rgba(30,10,10,0.62)", display: "flex", alignItems: "flex-end", zIndex: 50 }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: CARD, width: "100%", borderRadius: "22px 22px 0 0",
        padding: "22px 20px 28px", fontFamily: "Manrope, sans-serif", maxHeight: "88%", overflowY: "auto", boxSizing: "border-box",
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <div style={{ width: 34, height: 34, borderRadius: "50%", background: "#F9DEDE", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <Siren size={17} color={corDestaque} />
            </div>
            <span style={{ fontFamily: "Fraunces, serif", fontSize: 16.5, color: INK }}>Central de emergência</span>
          </div>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer" }}>
            <X size={18} color={INK} />
          </button>
        </div>
        <p style={{ fontSize: 11.5, color: INK_SOFT, marginBottom: 16, lineHeight: 1.5 }}>
          Se você está insegura ou precisa de ajuda agora, use uma das opções abaixo.
        </p>

        <div style={{ display: "flex", flexDirection: "column", gap: 9, marginBottom: 18 }}>
          <a href="tel:190" style={{
            display: "flex", alignItems: "center", gap: 10, textDecoration: "none",
            background: corDestaque, borderRadius: 12, padding: "13px 15px",
          }}>
            <PhoneCall size={17} color="#FFFFFF" />
            <div>
              <p style={{ fontSize: 13, fontWeight: 700, color: "#FFFFFF", margin: 0 }}>Ligar para a Polícia — 190</p>
              <p style={{ fontSize: 10.5, color: "rgba(255,255,255,0.85)", margin: 0 }}>Emergência policial</p>
            </div>
          </a>
          <a href="tel:180" style={{
            display: "flex", alignItems: "center", gap: 10, textDecoration: "none",
            background: "none", border: `1.5px solid ${corDestaque}`, borderRadius: 12, padding: "13px 15px",
          }}>
            <Phone size={17} color={corDestaque} />
            <div>
              <p style={{ fontSize: 13, fontWeight: 700, color: corDestaque, margin: 0 }}>Central de Atendimento à Mulher — 180</p>
              <p style={{ fontSize: 10.5, color: INK_SOFT, margin: 0 }}>Orientação e denúncia, 24h</p>
            </div>
          </a>
        </div>

        <p style={{ fontSize: 11, fontWeight: 700, color: "#8B6A52", marginBottom: 8 }}>COMPARTILHAR STATUS DO ATENDIMENTO</p>
        {contatos.length > 0 ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {enviado ? (
              <div style={{ display: "flex", alignItems: "flex-start", gap: 8, background: "#E4F1EC", borderRadius: 12, padding: "12px 14px" }}>
                <CheckCircle2 size={16} color={FOREST} style={{ flexShrink: 0, marginTop: 1 }} />
                <span style={{ fontSize: 12, color: FOREST, lineHeight: 1.5 }}>
                  Enviado para <b>{nomesContatos}</b> às {horaAgora()}: "{mensagem}"
                </span>
              </div>
            ) : (
              <button onClick={() => { setEnviado(true); onAvisar?.(contatos, mensagem); }} style={{
                width: "100%", display: "flex", alignItems: "center", gap: 10, textAlign: "left",
                background: PAPER, border: `1px solid ${LINE}`, borderRadius: 12, padding: "13px 14px", cursor: "pointer",
              }}>
                <MapPinned size={18} color={corDestaque} style={{ flexShrink: 0 }} />
                <span style={{ fontSize: 12.5, color: INK, lineHeight: 1.5 }}>
                  Avisar {contatos.length > 1 ? "meus contatos de confiança" : "meu contato de confiança"} (<b>{nomesContatos}</b>) sobre esse atendimento
                </span>
              </button>
            )}

            {compartilhandoLocal ? (
              <div style={{ display: "flex", alignItems: "center", gap: 10, background: "#FDEBEA", border: `1px solid ${corDestaque}`, borderRadius: 12, padding: "12px 14px" }}>
                <span style={{ width: 9, height: 9, borderRadius: "50%", background: corDestaque, flexShrink: 0 }} />
                <span style={{ fontSize: 12, color: "#7A2020", flex: 1 }}>
                  Compartilhando localização ao vivo há <b>{formatarTempo(segundosLocal)}</b>
                </span>
                <button onClick={() => { setCompartilhandoLocal(false); setSegundosLocal(0); }} style={{
                  background: "none", border: `1px solid ${corDestaque}`, borderRadius: 8, padding: "5px 9px",
                  color: corDestaque, fontSize: 10.5, fontWeight: 700, cursor: "pointer",
                }}>
                  Parar
                </button>
              </div>
            ) : (
              <button onClick={() => { setCompartilhandoLocal(true); onAvisar?.(contatos, `Comecei a compartilhar minha localização ao vivo (${contexto || "atendimento pelo app"}).`); }} style={{
                width: "100%", display: "flex", alignItems: "center", gap: 10, textAlign: "left",
                background: PAPER, border: `1px solid ${LINE}`, borderRadius: 12, padding: "13px 14px", cursor: "pointer",
              }}>
                <Radio size={18} color={corDestaque} style={{ flexShrink: 0 }} />
                <span style={{ fontSize: 12.5, color: INK, lineHeight: 1.5 }}>
                  Compartilhar minha localização ao vivo com {nomesContatos}
                </span>
              </button>
            )}
          </div>
        ) : (
          <div style={{ background: "#FBEBD9", border: `1px solid ${GOLD_DEEP}`, borderRadius: 12, padding: "12px 14px" }}>
            <p style={{ fontSize: 11.5, color: "#6B4A24", lineHeight: 1.5, marginBottom: onConfigurarContato ? 8 : 0 }}>
              Cadastre um contato de confiança no seu perfil para poder compartilhar sua localização rapidamente numa emergência.
            </p>
            {onConfigurarContato && (
              <button onClick={() => { onConfigurarContato(); onClose(); }} style={{
                background: "none", border: "none", color: GOLD_DEEP, fontWeight: 700, fontSize: 11.5, cursor: "pointer", padding: 0,
              }}>
                Configurar agora
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function AvisoSilenciosoButton({ meuContato, contexto, onAcionar, corDestaque = "#C23B3B" }) {
  const [estado, setEstado] = useState("idle"); // idle | enviado
  const contatos = meuContato?.contatosConfianca || [];
  if (contatos.length === 0) return null;

  const acionar = () => {
    setEstado("enviado");
    onAcionar?.(contatos, contexto);
    setTimeout(() => setEstado("idle"), 2600);
  };

  return (
    <button onClick={acionar} title="Aviso silencioso aos contatos de confiança (sem abrir alarme na tela)" style={{
      display: "flex", alignItems: "center", gap: 5, background: "none", border: "none", cursor: "pointer",
      color: estado === "enviado" ? FOREST : "#B08B76", padding: 0, fontFamily: "Manrope, sans-serif",
    }}>
      {estado === "enviado" ? <CheckCircle2 size={13} /> : <Vibrate size={13} />}
      <span style={{ fontSize: 10 }}>{estado === "enviado" ? "Aviso enviado" : "Aviso silencioso"}</span>
    </button>
  );
}

function DenunciarBloquearModal({ nome, onClose, onBloquear, onDenunciar, corDestaque = GOLD_DEEP }) {
  const [tela, setTela] = useState("menu"); // menu | bloquear | denunciar | denunciaEnviada
  const [motivo, setMotivo] = useState(null);
  const [detalhes, setDetalhes] = useState("");
  const motivos = ["Comportamento inadequado", "Cobrança indevida", "Perfil falso", "Assédio", "Outro"];

  return (
    <div style={{ position: "absolute", inset: 0, background: "rgba(22,64,60,0.6)", display: "flex", alignItems: "flex-end", zIndex: 40 }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: CARD, width: "100%", borderRadius: "22px 22px 0 0",
        padding: "22px 20px 28px", fontFamily: "Manrope, sans-serif", maxHeight: "85%", overflowY: "auto", boxSizing: "border-box",
      }}>
        {tela === "menu" && (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
              <span style={{ fontFamily: "Fraunces, serif", fontSize: 17, color: INK }}>{nome.split(" ")[0]}</span>
              <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer" }}>
                <X size={18} color={INK} />
              </button>
            </div>
            <button onClick={() => setTela("denunciar")} style={{
              width: "100%", display: "flex", alignItems: "center", gap: 10, textAlign: "left",
              background: "none", border: `1px solid ${LINE}`, borderRadius: 12, padding: "13px 14px", cursor: "pointer", marginBottom: 10,
            }}>
              <Flag size={17} color={GOLD_DEEP} />
              <div>
                <p style={{ fontSize: 13, fontWeight: 700, color: INK, margin: 0 }}>Denunciar perfil</p>
                <p style={{ fontSize: 10.5, color: "#8B6A52", margin: 0 }}>Nossa equipe vai analisar em até 48h</p>
              </div>
            </button>
            <button onClick={() => setTela("bloquear")} style={{
              width: "100%", display: "flex", alignItems: "center", gap: 10, textAlign: "left",
              background: "none", border: `1px solid ${ERROR}`, borderRadius: 12, padding: "13px 14px", cursor: "pointer",
            }}>
              <Ban size={17} color={ERROR} />
              <div>
                <p style={{ fontSize: 13, fontWeight: 700, color: ERROR, margin: 0 }}>Bloquear perfil</p>
                <p style={{ fontSize: 10.5, color: "#8B6A52", margin: 0 }}>Vocês não vão mais se ver no app</p>
              </div>
            </button>
          </>
        )}

        {tela === "bloquear" && (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
              <span style={{ fontFamily: "Fraunces, serif", fontSize: 17, color: INK }}>Bloquear {nome.split(" ")[0]}?</span>
              <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer" }}>
                <X size={18} color={INK} />
              </button>
            </div>
            <p style={{ fontSize: 12.5, color: INK_SOFT, marginBottom: 18, lineHeight: 1.55 }}>
              {nome.split(" ")[0]} não vai mais aparecer nas suas buscas e vocês não poderão mais conversar. Você pode desbloquear quando quiser, na sua tela de perfil.
            </p>
            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={() => setTela("menu")} style={{ ...btnSecondary, flex: 1 }}>Voltar</button>
              <button onClick={() => { onBloquear(); onClose(); }} style={{ ...btnPrimary, flex: 1, background: ERROR }}>
                <Ban size={15} /> Bloquear
              </button>
            </div>
          </>
        )}

        {tela === "denunciar" && (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
              <span style={{ fontFamily: "Fraunces, serif", fontSize: 17, color: INK }}>Denunciar {nome.split(" ")[0]}</span>
              <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer" }}>
                <X size={18} color={INK} />
              </button>
            </div>
            <p style={{ fontSize: 11.5, fontWeight: 700, color: INK_SOFT, marginBottom: 8 }}>Qual é o motivo?</p>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 14 }}>
              {motivos.map((m) => (
                <button key={m} onClick={() => setMotivo(m)} style={{
                  fontSize: 11.5, padding: "8px 12px", borderRadius: 20, cursor: "pointer",
                  border: `1.5px solid ${motivo === m ? corDestaque : LINE}`,
                  background: motivo === m ? corDestaque : "none",
                  color: motivo === m ? "#FFFFFF" : INK_SOFT, fontFamily: "Manrope, sans-serif",
                }}>
                  {m}
                </button>
              ))}
            </div>
            <p style={{ fontSize: 11.5, fontWeight: 700, color: INK_SOFT, marginBottom: 8 }}>Detalhes (opcional)</p>
            <textarea
              value={detalhes} onChange={(e) => setDetalhes(e.target.value)}
              placeholder="Conte o que aconteceu..."
              rows={3}
              style={{ ...inputStyle, width: "100%", resize: "vertical", marginBottom: 16, boxSizing: "border-box", fontFamily: "Manrope, sans-serif" }}
            />
            <button
              disabled={!motivo}
              onClick={() => { onDenunciar(motivo, detalhes.trim()); setTela("denunciaEnviada"); }}
              style={{ ...btnPrimary, width: "100%", background: corDestaque, opacity: motivo ? 1 : 0.5 }}
            >
              <Flag size={15} /> Enviar denúncia
            </button>
          </>
        )}

        {tela === "denunciaEnviada" && (
          <div style={{ textAlign: "center", padding: "10px 0" }}>
            <div style={{
              width: 56, height: 56, borderRadius: "50%", background: "#E4F1EC", display: "flex",
              alignItems: "center", justifyContent: "center", margin: "0 auto 14px",
            }}>
              <CheckCircle2 size={26} color={FOREST} />
            </div>
            <p style={{ fontSize: 13.5, color: INK, lineHeight: 1.6, marginBottom: 18 }}>
              Denúncia enviada. Nossa equipe de confiança e segurança vai analisar em até 48h. Obrigado por ajudar a manter o app seguro.
            </p>
            <button onClick={onClose} style={{ ...btnPrimary, background: corDestaque, width: "100%" }}>
              Entendi
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function BloqueadosScreen({ bloqueados, onVoltar, onDesbloquear, corDestaque = GOLD_DEEP, corHeader = INK, corTexto = PAPER }) {
  return (
    <div style={{ position: "absolute", inset: 0, background: PAPER, zIndex: 32, display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "16px 16px", background: corHeader }}>
        <button onClick={onVoltar} style={{ background: "none", border: "none", cursor: "pointer" }}>
          <ChevronLeft size={20} color={corTexto} />
        </button>
        <span style={{ color: corTexto, fontFamily: "Manrope, sans-serif", fontSize: 13.5 }}>Perfis bloqueados</span>
      </div>
      <div style={{ flex: 1, overflowY: "auto", padding: "18px 16px", fontFamily: "Manrope, sans-serif" }}>
        {bloqueados.length === 0 && (
          <div style={{ textAlign: "center", padding: "40px 10px" }}>
            <Ban size={28} color="#C7B8A3" style={{ marginBottom: 10 }} />
            <p style={{ fontSize: 12.5, color: "#8B6A52" }}>Você não bloqueou nenhum perfil.</p>
          </div>
        )}
        {bloqueados.map((p) => (
          <div key={`${p.tipo}-${p.id}`} style={{
            display: "flex", alignItems: "center", gap: 10, background: CARD, border: `1px solid ${LINE}`,
            borderRadius: 14, padding: "12px 14px", marginBottom: 10,
          }}>
            <span style={{ fontSize: 13, color: INK, flex: 1 }}>{p.nome}</span>
            <button onClick={() => onDesbloquear(p.tipo, p.id)} style={{
              fontSize: 11, fontWeight: 700, padding: "6px 12px", borderRadius: 9, cursor: "pointer",
              border: `1px solid ${corDestaque}`, background: "none", color: corDestaque,
            }}>
              Desbloquear
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

function PerfilMae({
  perfil, onVoltar, onSalvar, onAtualizarFoto, onVerContratacoes, onVerBloqueados, totalBloqueados = 0,
  corDestaque = GOLD, corHeader = INK, corTexto = PAPER, rotulo = "Pai ou mãe na Babá de Aluguel", appNome = "baba",
}) {
  const [edit, setEdit] = useState(null);
  const [showFotoModal, setShowFotoModal] = useState(false);
  const [showShare, setShowShare] = useState(false);
  const [testeEnviado, setTesteEnviado] = useState(false);
  const editando = edit !== null;
  const nome = (editando ? edit.nome : perfil?.nome) || "Sua conta";
  const partes = nome.trim().split(" ").filter(Boolean);
  const iniciais = ((partes[0]?.[0] || "M") + (partes[1]?.[0] || partes[0]?.[1] || "")).toUpperCase();
  const seguidores = perfil?.seguidores ?? 0;
  const seguindo = perfil?.seguindo ?? 0;

  const iniciarEdicao = () => {
    setEdit({
      nome: perfil?.nome || "", email: perfil?.email || "", bairro: perfil?.bairro || "",
      contatosConfianca: perfil?.contatosConfianca || [],
    });
  };

  const salvar = () => {
    const contatosValidos = (edit.contatosConfianca || []).filter((c) => c.nome.trim() && c.telefone.trim());
    onSalvar?.({
      nome: edit.nome.trim() || "Sua conta",
      email: edit.email.trim(),
      bairro: edit.bairro.trim(),
      contatosConfianca: edit.contatosConfianca || [],
    });
    setEdit(null);
    if (contatosValidos.length > 0) {
      setTesteEnviado(true);
      setTimeout(() => setTesteEnviado(false), 4000);
    }
  };

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "16px 16px", background: corHeader }}>
        <button onClick={onVoltar} style={{ background: "none", border: "none", cursor: "pointer" }}>
          <ChevronLeft size={20} color={corTexto} />
        </button>
        <span style={{ color: corTexto, fontFamily: "Manrope, sans-serif", fontSize: 13.5, flex: 1 }}>Meu perfil</span>
        <button onClick={() => setShowShare(true)} title="Compartilhar perfil" style={{
          display: "flex", alignItems: "center", justifyContent: "center", width: 28, height: 28,
          borderRadius: "50%", background: "rgba(201,138,86,0.16)", border: `1px solid ${corDestaque}`, cursor: "pointer",
        }}>
          <Share2 size={12} color={corDestaque} />
        </button>
        {!editando ? (
          <button onClick={iniciarEdicao} style={{
            display: "flex", alignItems: "center", gap: 5, background: "rgba(201,138,86,0.16)",
            border: `1px solid ${corDestaque}`, borderRadius: 20, padding: "6px 11px", cursor: "pointer",
          }}>
            <Edit3 size={12} color={corDestaque} />
            <span style={{ fontSize: 10.5, color: corTexto, fontFamily: "Manrope, sans-serif" }}>Editar</span>
          </button>
        ) : (
          <div style={{ display: "flex", gap: 6 }}>
            <button onClick={() => setEdit(null)} style={{
              background: "none", border: `1px solid ${corTexto}`, borderRadius: 20, padding: "6px 11px", cursor: "pointer",
            }}>
              <span style={{ fontSize: 10.5, color: corTexto, fontFamily: "Manrope, sans-serif" }}>Cancelar</span>
            </button>
            <button onClick={salvar} style={{
              display: "flex", alignItems: "center", gap: 5, background: corDestaque,
              border: "none", borderRadius: 20, padding: "6px 11px", cursor: "pointer",
            }}>
              <Check size={12} color="#4A2A12" />
              <span style={{ fontSize: 10.5, color: "#4A2A12", fontFamily: "Manrope, sans-serif", fontWeight: 700 }}>Salvar</span>
            </button>
          </div>
        )}
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "22px 20px", fontFamily: "Manrope, sans-serif" }}>
        {testeEnviado && (
          <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#E4F1EC", border: `1px solid ${FOREST}`, borderRadius: 12, padding: "10px 13px", marginBottom: 14 }}>
            <CheckCircle2 size={14} color={FOREST} style={{ flexShrink: 0 }} />
            <span style={{ fontSize: 11.5, color: FOREST }}>Mensagem de teste enviada para o(s) seu(s) contato(s) de confiança.</span>
          </div>
        )}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: 18 }}>
          <div style={{ position: "relative" }}>
            <Avatar initials={iniciais} color={WINE} fotoUrl={perfil?.fotoUrl} size={72} />
            <button onClick={() => setShowFotoModal(true)} title="Alterar foto" style={{
              position: "absolute", bottom: -2, right: -2, width: 24, height: 24, borderRadius: "50%",
              background: corDestaque, border: `2px solid ${CARD}`, display: "flex", alignItems: "center",
              justifyContent: "center", cursor: "pointer",
            }}>
              <Camera size={12} color="#4A2A12" />
            </button>
          </div>
          {editando ? (
            <input
              style={{ ...inputStyle, marginTop: 12, textAlign: "center", maxWidth: 240 }}
              value={edit.nome} onChange={(e) => setEdit({ ...edit, nome: e.target.value })}
              placeholder="Nome completo"
            />
          ) : (
            <p style={{ fontFamily: "Fraunces, serif", fontSize: 19, color: INK, fontWeight: 600, marginTop: 12 }}>
              {nome}
            </p>
          )}
          <span style={{ fontSize: 11, color: "#8B6A52", marginTop: 4 }}>{rotulo}</span>

          <div style={{ display: "flex", alignItems: "center", gap: 14, marginTop: 12 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
              <Users size={13} color="#8B6A52" />
              <span style={{ fontSize: 12, color: "#8B6A52" }}>
                <b style={{ color: INK }}>{seguidores}</b> seguidores
              </span>
            </div>
            <div style={{ width: 1, height: 12, background: LINE }} />
            <span style={{ fontSize: 12, color: "#8B6A52" }}>
              <b style={{ color: INK }}>{seguindo}</b> seguindo
            </span>
          </div>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {editando ? (
            <>
              <CampoEdit label="E-mail">
                <input style={inputStyle} type="email" value={edit.email} onChange={(e) => setEdit({ ...edit, email: e.target.value })} placeholder="seuemail@exemplo.com" />
              </CampoEdit>
              <CampoEdit label="Bairro">
                <input style={inputStyle} value={edit.bairro} onChange={(e) => setEdit({ ...edit, bairro: e.target.value })} placeholder="Seu bairro" />
              </CampoEdit>
              <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 6, marginBottom: 2 }}>
                <Siren size={13} color={ERROR} />
                <p style={{ fontSize: 11, fontWeight: 700, color: ERROR, margin: 0 }}>Contatos de confiança (emergência)</p>
              </div>
              <ContatoConfiancaEditor
                contatos={edit.contatosConfianca}
                onChange={(novos) => setEdit({ ...edit, contatosConfianca: novos })}
                corDestaque={ERROR}
              />
            </>
          ) : (
            <>
              <div style={{ background: CARD, border: `1px solid ${LINE}`, borderRadius: 12, padding: "12px 14px" }}>
                <p style={{ fontSize: 10.5, color: "#8B6A52", marginBottom: 3 }}>E-mail</p>
                <p style={{ fontSize: 13, color: INK }}>{perfil?.email || "Não informado"}</p>
              </div>
              <div style={{ background: CARD, border: `1px solid ${LINE}`, borderRadius: 12, padding: "12px 14px" }}>
                <p style={{ fontSize: 10.5, color: "#8B6A52", marginBottom: 3 }}>Bairro</p>
                <p style={{ fontSize: 13, color: INK }}>{perfil?.bairro || "Não informado"}</p>
              </div>
              <div style={{ background: CARD, border: `1px solid ${LINE}`, borderRadius: 12, padding: "12px 14px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 5, marginBottom: 3 }}>
                  <Siren size={11} color={ERROR} />
                  <p style={{ fontSize: 10.5, color: "#8B6A52", margin: 0 }}>Contatos de confiança</p>
                </div>
                <ContatosConfiancaView contatos={perfil?.contatosConfianca} />
              </div>
            </>
          )}
        </div>

        {!editando && (
          <button onClick={onVerContratacoes} style={{
            display: "flex", alignItems: "center", gap: 10, width: "100%", marginTop: 16,
            background: CARD, border: `1px solid ${LINE}`, borderRadius: 12, padding: "13px 14px",
            cursor: "pointer", textAlign: "left",
          }}>
            <ClipboardList size={16} color={corDestaque} />
            <span style={{ fontSize: 13, color: INK, fontFamily: "Manrope, sans-serif", flex: 1 }}>Minhas contratações</span>
            <ChevronLeft size={14} color="#8B6A52" style={{ transform: "rotate(180deg)" }} />
          </button>
        )}
        {!editando && onVerBloqueados && (
          <button onClick={onVerBloqueados} style={{
            display: "flex", alignItems: "center", gap: 10, width: "100%", marginTop: 10,
            background: CARD, border: `1px solid ${LINE}`, borderRadius: 12, padding: "13px 14px",
            cursor: "pointer", textAlign: "left",
          }}>
            <Ban size={16} color={corDestaque} />
            <span style={{ fontSize: 13, color: INK, fontFamily: "Manrope, sans-serif", flex: 1 }}>
              Perfis bloqueados{totalBloqueados > 0 ? ` (${totalBloqueados})` : ""}
            </span>
            <ChevronLeft size={14} color="#8B6A52" style={{ transform: "rotate(180deg)" }} />
          </button>
        )}

        {!perfil && !editando && (
          <p style={{ fontSize: 11.5, color: "#8B6A52", textAlign: "center", marginTop: 20, lineHeight: 1.6 }}>
            Toque em "Editar" para preencher e-mail e bairro aqui.
          </p>
        )}
      </div>

      {showFotoModal && (
        <FotoModal
          titulo="Foto de perfil"
          textoBotao="Salvar foto"
          onClose={() => setShowFotoModal(false)}
          onSalvar={(foto) => {
            onAtualizarFoto?.(foto);
            setShowFotoModal(false);
          }}
        />
      )}
      {showShare && <ShareModal nome={nome} appNome={appNome} corDestaque={corDestaque} onClose={() => setShowShare(false)} />}
    </div>
  );
}

