function DiaristaLoginScreen({ tipo, setTipo, onEntrar, onCadastro, onVoltar }) {
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [erro, setErro] = useState("");
  const [showSac, setShowSac] = useState(false);
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const [tentativas, setTentativas] = useState(0);
  const [bloqueadoAte, setBloqueadoAte] = useState(0);
  const [recuperacaoEnviada, setRecuperacaoEnviada] = useState(false);
  const [agora, setAgora] = useState(Date.now());

  useEffect(() => {
    if (!bloqueadoAte) return;
    const t = setInterval(() => setAgora(Date.now()), 500);
    return () => clearInterval(t);
  }, [bloqueadoAte]);

  const bloqueado = bloqueadoAte > agora;
  const segundosRestantes = bloqueado ? Math.ceil((bloqueadoAte - agora) / 1000) : 0;

  const entrar = () => {
    if (bloqueado) return;
    if (!email.trim() || !senha.trim() || !email.includes("@")) {
      const proximaTentativa = tentativas + 1;
      if (proximaTentativa >= 5) {
        setBloqueadoAte(Date.now() + 30000);
        setTentativas(0);
        setErro("Muitas tentativas seguidas. Por segurança, aguarde 30 segundos para tentar de novo.");
      } else {
        setTentativas(proximaTentativa);
        setErro(!email.trim() || !senha.trim() ? "Preencha e-mail e senha para continuar." : "Digite um e-mail válido.");
      }
      return;
    }
    setErro("");
    setTentativas(0);
    onEntrar(tipo);
  };

  return (
    <div style={{
      flex: 1, display: "flex", flexDirection: "column", alignItems: "center",
      justifyContent: "center", padding: "28px 26px", background: "#FFF6F1", overflowY: "auto",
      position: "relative",
    }}>
      <button onClick={onVoltar} style={{
        position: "absolute", top: 16, left: 16, background: "none", border: "none",
        cursor: "pointer", color: D_CORAL_DEEP, display: "flex", alignItems: "center",
      }}>
        <ChevronLeft size={22} />
      </button>

      <LogoBrilho width={110} style={{ marginBottom: 14 }} src={LOGO_DIARISTA_B64} alt="Diarista de Aluguel" />

      <div style={{ width: "100%" }}>
        <p style={{ fontSize: 11.5, color: "#8B6A52", fontFamily: "Manrope, sans-serif", marginBottom: 8, textAlign: "center" }}>
          Quero acessar como
        </p>
        <RoleToggleDiarista tipo={tipo} setTipo={setTipo} />
      </div>

      <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 12 }}>
        <div>
          <label style={{ fontSize: 11.5, color: "#8B6A52", fontFamily: "Manrope, sans-serif", marginBottom: 5, display: "block" }}>
            E-mail
          </label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="seuemail@exemplo.com"
            style={{
              width: "100%", boxSizing: "border-box", border: `1px solid #F3D9D5`,
              borderRadius: 12, padding: "12px 14px", fontSize: 13.5,
              fontFamily: "Manrope, sans-serif", background: "#FFFFFF", color: "#5A2420", outline: "none",
            }}
          />
        </div>
        <div>
          <label style={{ fontSize: 11.5, color: "#8B6A52", fontFamily: "Manrope, sans-serif", marginBottom: 5, display: "block" }}>
            Senha
          </label>
          <div style={{ position: "relative" }}>
            <input
              type={mostrarSenha ? "text" : "password"}
              value={senha}
              onChange={(e) => setSenha(e.target.value)}
              placeholder="Digite sua senha"
              onKeyDown={(e) => e.key === "Enter" && entrar()}
              disabled={bloqueado}
              style={{
                width: "100%", boxSizing: "border-box", border: `1px solid #F3D9D5`,
                borderRadius: 12, padding: "12px 42px 12px 14px", fontSize: 13.5,
                fontFamily: "Manrope, sans-serif", background: bloqueado ? "#F0E4E0" : "#FFFFFF", color: "#5A2420", outline: "none",
              }}
            />
            <button type="button" onClick={() => setMostrarSenha((v) => !v)} style={{
              position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)",
              background: "none", border: "none", cursor: "pointer", color: "#8B6A52", display: "flex",
            }}>
              {mostrarSenha ? <EyeOff size={16} /> : <Eye size={16} />}
            </button>
          </div>
        </div>

        {erro && (
          <p style={{ fontSize: 11.5, color: ERROR, fontFamily: "Manrope, sans-serif", margin: 0, display: "flex", alignItems: "flex-start", gap: 5 }}>
            {bloqueado && <ShieldAlert size={13} style={{ flexShrink: 0, marginTop: 1 }} />} {erro}
          </p>
        )}
        {bloqueado && (
          <p style={{ fontSize: 11, color: "#8B6A52", fontFamily: "Manrope, sans-serif", margin: 0 }}>
            Você poderá tentar de novo em {segundosRestantes}s.
          </p>
        )}

        <button className="shine-cta" onClick={entrar} disabled={bloqueado} style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          background: `linear-gradient(120deg, ${D_CORAL_LIGHT} 0%, ${D_CORAL} 55%, ${D_CORAL_DEEP} 100%)`,
          color: "#FFFFFF", border: "none", borderRadius: 12,
          padding: "13px 16px", fontFamily: "Manrope, sans-serif", fontWeight: 700,
          fontSize: 14, cursor: bloqueado ? "default" : "pointer", boxShadow: "0 4px 14px rgba(201,68,48,0.35)",
          width: "100%", marginTop: 6, opacity: bloqueado ? 0.55 : 1,
        }}>
          {bloqueado ? <Lock size={15} /> : null} Entrar como {tipo === "diarista" ? "diarista" : "cliente"}
        </button>

        {recuperacaoEnviada ? (
          <p style={{ fontSize: 11, color: "#8B6A52", textAlign: "center", marginTop: 2, lineHeight: 1.5 }}>
            Se esse e-mail tiver uma conta, enviamos um link para redefinir a senha.
          </p>
        ) : (
          <button onClick={() => email.includes("@") && setRecuperacaoEnviada(true)} style={{
            background: "none", border: "none", color: "#8B6A52", fontFamily: "Manrope, sans-serif",
            fontSize: 12, cursor: "pointer", marginTop: 2,
          }}>
            Esqueci minha senha
          </button>
        )}
      </div>

      <p style={{ fontSize: 11.5, color: "#8B6A52", fontFamily: "Manrope, sans-serif", marginTop: 24, textAlign: "center" }}>
        Ainda não tem conta?{" "}
        <span onClick={() => onCadastro(tipo)} style={{ color: D_CORAL_DEEP, fontWeight: 700, cursor: "pointer" }}>
          Cadastre-se como {tipo === "diarista" ? "diarista" : "cliente"}
        </span>
      </p>

      <div style={{ marginTop: 16, textAlign: "center" }}>
        <p style={{ fontSize: 11, color: "#8B6A52", fontFamily: "Manrope, sans-serif", marginBottom: 4 }}>
          Dúvidas sobre pagamento, cancelamento ou ajuda?
        </p>
        <button onClick={() => setShowSac(true)} style={{
          display: "inline-flex", alignItems: "center", gap: 5, background: "none", border: "none",
          cursor: "pointer", color: D_CORAL_DEEP, fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 11.5,
        }}>
          <Phone size={12} /> Fale com o SAC
        </button>
      </div>

      {showSac && <SACModal onClose={() => setShowSac(false)} corDestaque={D_CORAL_DEEP} email="sac@diaristadealuguel.com.br" />}
    </div>
  );
}

