function ChipsMulti({ options, value, onChange }) {
  const toggle = (opt) => {
    if (value.includes(opt)) onChange(value.filter((v) => v !== opt));
    else onChange([...value, opt]);
  };
  return (
    <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>
      {options.map((opt) => (
        <button key={opt} onClick={() => toggle(opt)} style={{
          padding: "8px 14px", borderRadius: 20, cursor: "pointer",
          border: `1.5px solid ${value.includes(opt) ? GOLD_DEEP : LINE}`,
          background: value.includes(opt) ? GOLD : CARD,
          color: value.includes(opt) ? "#4A2A12" : INK_SOFT,
          fontFamily: "Manrope, sans-serif", fontWeight: value.includes(opt) ? 700 : 500, fontSize: 12.5,
        }}>
          {opt}
        </button>
      ))}
    </div>
  );
}

