// ---- captura de foto só pela câmera (sem acesso à galeria, evita fraude) ----

function FotoCameraStep({ foto, setFoto }) {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const [erroCamera, setErroCamera] = useState("");
  const [carregando, setCarregando] = useState(true);

  useEffect(() => {
    if (foto) return; // já tem foto, não precisa da câmera ligada
    let cancelado = false;
    setCarregando(true);
    setErroCamera("");
    navigator.mediaDevices?.getUserMedia?.({ video: { facingMode: "user" }, audio: false })
      .then((stream) => {
        if (cancelado) { stream.getTracks().forEach((t) => t.stop()); return; }
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play().catch(() => {});
        }
        setCarregando(false);
      })
      .catch(() => {
        setErroCamera("Não conseguimos acessar sua câmera. Verifique as permissões do navegador e tente novamente.");
        setCarregando(false);
      });
    return () => {
      cancelado = true;
      streamRef.current?.getTracks().forEach((t) => t.stop());
    };
  }, [foto]);

  const tirarFoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;
    const tamanho = Math.min(video.videoWidth, video.videoHeight);
    canvas.width = tamanho;
    canvas.height = tamanho;
    const ctx = canvas.getContext("2d");
    const offsetX = (video.videoWidth - tamanho) / 2;
    const offsetY = (video.videoHeight - tamanho) / 2;
    ctx.translate(tamanho, 0);
    ctx.scale(-1, 1);
    ctx.drawImage(video, offsetX, offsetY, tamanho, tamanho, 0, 0, tamanho, tamanho);
    const dataUrl = canvas.toDataURL("image/jpeg", 0.85);
    setFoto(dataUrl);
    streamRef.current?.getTracks().forEach((t) => t.stop());
  };

  const refazer = () => setFoto(null);

  return (
    <div>
      <div style={{
        width: "100%", aspectRatio: "1 / 1", borderRadius: 18, overflow: "hidden",
        background: "#12302C", position: "relative", marginBottom: 14,
      }}>
        {foto ? (
          <img src={foto} alt="Sua foto" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <>
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              style={{ width: "100%", height: "100%", objectFit: "cover", transform: "scaleX(-1)" }}
            />
            {carregando && !erroCamera && (
              <div style={{
                position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center",
                color: "#D8C3A8", fontFamily: "Manrope, sans-serif", fontSize: 12,
              }}>
                Abrindo câmera…
              </div>
            )}
            {erroCamera && (
              <div style={{
                position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center",
                padding: 18, textAlign: "center", color: "#E8C9C9", fontFamily: "Manrope, sans-serif", fontSize: 12,
              }}>
                {erroCamera}
              </div>
            )}
          </>
        )}
      </div>
      <canvas ref={canvasRef} style={{ display: "none" }} />

      {!foto ? (
        <button className="shine-cta" onClick={tirarFoto} disabled={carregando || !!erroCamera} style={{
          ...btnPrimary, width: "100%",
          opacity: carregando || erroCamera ? 0.5 : 1,
          cursor: carregando || erroCamera ? "not-allowed" : "pointer",
        }}>
          <Camera size={16} /> Tirar foto
        </button>
      ) : (
        <button onClick={refazer} style={{ ...btnSecondary, width: "100%" }}>
          <RefreshCw size={16} /> Tirar novamente
        </button>
      )}

      <p style={{ fontSize: 11, color: "#8B6A52", fontFamily: "Manrope, sans-serif", marginTop: 10, textAlign: "center" }}>
        Por segurança, a foto do seu perfil só pode ser tirada agora, na hora, pela câmera. Não é possível
        enviar uma imagem da galeria.
      </p>
    </div>
  );
}

