// ---- app ----

export default function App() {
  const [tela, setTela] = useState("hub");
  // tela: hub | login | cadastroMae | cadastroBaba | confirmacaoPagamento | confirmacaoEmailMae | confirmacaoEmailBaba | app | impulsionamento
  //     | diaristaLogin | cadastroDiarista | confirmacaoPagamentoDiarista | confirmacaoEmailDiarista
  //     | cadastroClienteDiarista | confirmacaoEmailClienteDiarista | diaristaApp
  const [tipoLogin, setTipoLogin] = useState("mae");
  const [modo, setModo] = useState("mae");
  const [selecionada, setSelecionada] = useState(null);
  const [meuPerfilBaba, setMeuPerfilBaba] = useState(minhaBaba);
  const [meuPerfilMae, setMeuPerfilMae] = useState(null);
  const [verPerfilMae, setVerPerfilMae] = useState(false);
  const [perfilPendente, setPerfilPendente] = useState(null);
  const [dadosMaePendente, setDadosMaePendente] = useState(null);
  const [boosts, setBoosts] = useState({});
  const [contratacoes, setContratacoes] = useState([]);
  const [verHistorico, setVerHistorico] = useState(null); // null | "cliente" | "prestadorBaba" | "prestadorDiarista"
  const [avaliando, setAvaliando] = useState(null); // contratação sendo avaliada
  const [avaliacoesExtras, setAvaliacoesExtras] = useState([]);
  const [notificacoes, setNotificacoes] = useState([
    { id: 1, texto: "Bem-vinda! Complete seu perfil para aparecer melhor nas buscas.", lida: true },
  ]);
  const [verNotificacoes, setVerNotificacoes] = useState(false);

  const adicionarNotificacao = (texto) => {
    const novoId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    setNotificacoes((n) => [{ id: novoId, texto, lida: false }, ...n]);
  };

  const notificarContatosConfianca = (contatos, mensagem) => {
    const nomes = (contatos || []).map((c) => c.nome).filter(Boolean).join(", ");
    if (!nomes) return;
    adicionarNotificacao(`Avisamos ${nomes}: "${mensagem}"`);
  };

  const [tipoLoginDiarista, setTipoLoginDiarista] = useState("cliente");
  const [modoDiarista, setModoDiarista] = useState("cliente");
  const [meuPerfilDiarista, setMeuPerfilDiarista] = useState(minhaDiarista);
  const [selecionadaDiarista, setSelecionadaDiarista] = useState(null);
  const [perfilDiaristaPendente, setPerfilDiaristaPendente] = useState(null);
  const [meuPerfilCliente, setMeuPerfilCliente] = useState({ nome: "Cliente Exemplo", email: "cliente@exemplo.com", bairro: "Tatuapé", seguidores: 6, seguindo: 15 });
  const [verPerfilCliente, setVerPerfilCliente] = useState(false);
  const [dadosClientePendente, setDadosClientePendente] = useState(null);

  const [perfisBloqueados, setPerfisBloqueados] = useState([]); // [{ tipo: "baba"|"diarista", id, nome }]
  const [denuncias, setDenuncias] = useState([]);
  const [verBloqueados, setVerBloqueados] = useState(false);

  const fazerLogin = (tipo) => {
    setModo(tipo);
    setTela("app");
  };

  const irParaCadastro = (tipo) => {
    setTela(tipo === "mae" ? "cadastroMae" : "cadastroBaba");
  };

  const cadastroMaeEnviado = (dados) => {
    setDadosMaePendente(dados);
    setTela("confirmacaoEmailMae");
  };

  const confirmarEmailMae = () => {
    setMeuPerfilMae({ ...dadosMaePendente, seguidores: 12, seguindo: 24 });
    setModo("mae");
    setTela("app");
  };

  const finalizarCadastroBaba = (respostas) => {
    const perfil = construirPerfilBaba(respostas);
    setPerfilPendente(perfil);
    setTela("confirmacaoPagamento");
  };

  const pagamentoConfirmado = () => {
    setTela("confirmacaoEmailBaba");
  };

  const confirmarEmailBaba = () => {
    setMeuPerfilBaba(perfilPendente);
    setModo("baba");
    setTela("app");
  };

  const atualizarFotoPerfil = (fotoUrl) => {
    setMeuPerfilBaba((p) => ({ ...p, fotoUrl }));
    setSelecionada((s) => (s ? { ...s, fotoUrl } : s));
  };

  const atualizarPerfilBaba = (dados) => {
    setMeuPerfilBaba((p) => ({ ...p, ...dados }));
    setSelecionada((s) => (s ? { ...s, ...dados } : s));
  };

  const atualizarPerfilMae = (dados) => {
    setMeuPerfilMae((p) => ({ ...(p || {}), ...dados }));
  };

  const atualizarFotoPerfilMae = (fotoUrl) => {
    setMeuPerfilMae((p) => ({ ...(p || {}), fotoUrl }));
  };

  const ativarImpulsionamento = (planoKey, duracao) => {
    setBoosts((b) => ({ ...b, [planoKey]: { ativo: true, dias: duracao.dias } }));
  };

  const agendarServico = (prestador, tipoPrestador, dados) => {
    const clienteNome = tipoPrestador === "baba" ? (meuPerfilMae?.nome || "Você") : (meuPerfilCliente?.nome || "Você");
    const nova = {
      id: Date.now(),
      prestadorId: prestador.id,
      prestadorTipo: tipoPrestador,
      prestadorNome: prestador.name,
      prestadorIniciais: prestador.initials,
      prestadorCor: prestador.color,
      prestadorFoto: prestador.fotoUrl,
      clienteNome,
      data: dados.data,
      horario: dados.horario,
      servico: dados.servico,
      valor: dados.valor,
      status: "pendente",
      avaliado: false,
    };
    setContratacoes((c) => [nova, ...c]);
    adicionarNotificacao(`Pedido enviado para ${prestador.name.split(" ")[0]}. Você será avisada assim que ela confirmar o dia ${dados.data} às ${dados.horario}.`);
  };

  const aceitarContratacao = (id) => {
    const alvo = contratacoes.find((x) => x.id === id);
    setContratacoes((c) => c.map((x) => (x.id === id ? { ...x, status: "agendado" } : x)));
    if (alvo) {
      adicionarNotificacao(`Você confirmou o atendimento com ${alvo.clienteNome.split(" ")[0]} em ${alvo.data} às ${alvo.horario}.`);
      const clienteContatos = alvo.prestadorTipo === "baba" ? meuPerfilMae?.contatosConfianca : meuPerfilCliente?.contatosConfianca;
      notificarContatosConfianca(clienteContatos, `Atendimento com ${alvo.prestadorNome} confirmado para ${alvo.data} às ${alvo.horario}.`);
    }
  };

  const registrarCheckin = (id) => {
    const alvo = contratacoes.find((x) => x.id === id);
    const agora = new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
    setContratacoes((c) => c.map((x) => (x.id === id ? { ...x, checkin: agora } : x)));
    if (alvo) {
      const meusContatos = alvo.prestadorTipo === "baba" ? meuPerfilBaba?.contatosConfianca : meuPerfilDiarista?.contatosConfianca;
      notificarContatosConfianca(meusContatos, `Cheguei para atender ${alvo.clienteNome} às ${agora}.`);
    }
  };

  const registrarCheckout = (id) => {
    const alvo = contratacoes.find((x) => x.id === id);
    const agora = new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
    setContratacoes((c) => c.map((x) => (x.id === id ? { ...x, checkout: agora } : x)));
    if (alvo) {
      const meusContatos = alvo.prestadorTipo === "baba" ? meuPerfilBaba?.contatosConfianca : meuPerfilDiarista?.contatosConfianca;
      notificarContatosConfianca(meusContatos, `Saí do atendimento com ${alvo.clienteNome} às ${agora}.`);
    }
  };

  const recusarContratacao = (id) => {
    const alvo = contratacoes.find((x) => x.id === id);
    setContratacoes((c) => c.map((x) => (x.id === id ? { ...x, status: "recusado" } : x)));
    if (alvo) adicionarNotificacao(`Você recusou o pedido de ${alvo.clienteNome.split(" ")[0]} para ${alvo.data}.`);
  };

  const concluirContratacao = (id) => {
    setContratacoes((c) => c.map((x) => (x.id === id ? { ...x, status: "concluido" } : x)));
  };

  const cancelarContratacao = (id) => {
    setContratacoes((c) => c.map((x) => (x.id === id ? { ...x, status: "cancelado" } : x)));
  };

  const abrirAvaliacao = (contratacao) => setAvaliando(contratacao);

  const enviarAvaliacao = ({ estrelas, comentario }) => {
    if (!avaliando) return;
    setContratacoes((c) => c.map((x) => (x.id === avaliando.id ? { ...x, avaliado: true } : x)));
    setAvaliacoesExtras((a) => [...a, {
      prestadorId: avaliando.prestadorId, prestadorTipo: avaliando.prestadorTipo,
      estrelas, comentario, autor: avaliando.clienteNome,
    }]);
    adicionarNotificacao(`Sua avaliação para ${avaliando.prestadorNome.split(" ")[0]} foi publicada.`);
    setAvaliando(null);
  };

  const fazerLoginDiarista = (tipo) => {
    setModoDiarista(tipo);
    setSelecionadaDiarista(null);
    setTela("diaristaApp");
  };

  const irParaCadastroDiarista = (tipo) => {
    if (tipo === "diarista") {
      setTela("cadastroDiarista");
    } else {
      setTela("cadastroClienteDiarista");
    }
  };

  const cadastroClienteDiaristaEnviado = (dados) => {
    setDadosClientePendente(dados);
    setTela("confirmacaoEmailClienteDiarista");
  };

  const confirmarEmailClienteDiarista = () => {
    setMeuPerfilCliente({ ...dadosClientePendente, seguidores: 12, seguindo: 24 });
    setModoDiarista("cliente");
    setSelecionadaDiarista(null);
    setTela("diaristaApp");
  };

  const finalizarCadastroDiarista = (respostas) => {
    const perfil = construirPerfilDiarista(respostas);
    setPerfilDiaristaPendente(perfil);
    setTela("confirmacaoPagamentoDiarista");
  };

  const pagamentoConfirmadoDiarista = () => {
    setTela("confirmacaoEmailDiarista");
  };

  const confirmarEmailDiarista = () => {
    setMeuPerfilDiarista(perfilDiaristaPendente);
    setModoDiarista("diarista");
    setSelecionadaDiarista(null);
    setTela("diaristaApp");
  };

  const atualizarFotoPerfilDiarista = (fotoUrl) => {
    setMeuPerfilDiarista((p) => ({ ...p, fotoUrl }));
    setSelecionadaDiarista((s) => (s ? { ...s, fotoUrl } : s));
  };

  const adicionarTrabalhoDiarista = (trabalho) => {
    setMeuPerfilDiarista((p) => ({ ...p, trabalhos: [...p.trabalhos, { id: Date.now(), ...trabalho }] }));
  };

  const atualizarPerfilDiarista = (dados) => {
    setMeuPerfilDiarista((p) => ({ ...p, ...dados }));
    setSelecionadaDiarista((s) => (s ? { ...s, ...dados } : s));
  };

  const atualizarPerfilCliente = (dados) => {
    setMeuPerfilCliente((p) => ({ ...(p || {}), ...dados }));
  };

  const atualizarFotoPerfilCliente = (fotoUrl) => {
    setMeuPerfilCliente((p) => ({ ...(p || {}), fotoUrl }));
  };

  const bloquearPerfil = (perfil, tipo) => {
    setPerfisBloqueados((b) => (b.some((p) => p.tipo === tipo && p.id === perfil.id) ? b : [...b, { tipo, id: perfil.id, nome: perfil.name }]));
    if (tipo === "baba") setSelecionada(null); else setSelecionadaDiarista(null);
    adicionarNotificacao(`Você bloqueou ${perfil.name.split(" ")[0]}. O perfil não vai mais aparecer para você.`);
  };

  const desbloquearPerfil = (tipo, id) => {
    setPerfisBloqueados((b) => b.filter((p) => !(p.tipo === tipo && p.id === id)));
  };

  const enviarDenuncia = (perfil, tipo, motivo, detalhes) => {
    setDenuncias((d) => [...d, {
      id: Date.now(), tipo, perfilId: perfil.id, perfilNome: perfil.name, motivo, detalhes,
      data: new Date().toLocaleDateString("pt-BR"),
    }]);
    adicionarNotificacao(`Sua denúncia sobre ${perfil.name.split(" ")[0]} foi enviada. Nossa equipe vai analisar em até 48h.`);
  };

  const idsBloqueadosBaba = perfisBloqueados.filter((p) => p.tipo === "baba").map((p) => p.id);
  const idsBloqueadosDiarista = perfisBloqueados.filter((p) => p.tipo === "diarista").map((p) => p.id);
  const pendentesBaba = contratacoes.filter((c) => c.prestadorTipo === "baba" && c.prestadorId === meuPerfilBaba.id && c.status === "pendente").length;
  const pendentesDiarista = contratacoes.filter((c) => c.prestadorTipo === "diarista" && c.prestadorId === meuPerfilDiarista.id && c.status === "pendente").length;

  return (
    <div style={{ display: "flex", justifyContent: "center", background: "#EFE3D0", padding: "28px 12px", minHeight: 680 }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@500;600&family=Manrope:wght@400;500;700&display=swap');
        @keyframes logo-shine-sweep {
          0% { left: -160%; }
          35% { left: 160%; }
          100% { left: 160%; }
        }
        .shine-cta { position: relative; overflow: hidden; }
        .shine-cta::after {
          content: "";
          position: absolute;
          top: 0;
          left: -160%;
          width: 45%;
          height: 100%;
          background: linear-gradient(115deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0) 35%, rgba(255,255,255,0.65) 50%, rgba(255,255,255,0) 65%, rgba(255,255,255,0) 100%);
          transform: skewX(-18deg);
          animation: logo-shine-sweep 3.2s ease-in-out infinite;
          pointer-events: none;
        }
      `}</style>
      <div style={{
        width: 380, height: 730, background: PAPER, borderRadius: 30,
        overflow: "hidden", boxShadow: "0 24px 48px rgba(22,64,60,0.22)",
        border: "7px solid #12302C", display: "flex", flexDirection: "column", position: "relative",
      }}>
        {tela === "hub" && (
          <HubScreen
            onEscolherBaba={() => setTela("login")}
            onEscolherDiarista={() => setTela("diaristaLogin")}
          />
        )}

        {tela === "diaristaLogin" && (
          <DiaristaLoginScreen
            tipo={tipoLoginDiarista}
            setTipo={setTipoLoginDiarista}
            onEntrar={fazerLoginDiarista}
            onCadastro={irParaCadastroDiarista}
            onVoltar={() => setTela("hub")}
          />
        )}

        {tela === "cadastroDiarista" && (
          <CadastroBaba
            perguntas={perguntasDiarista}
            onVoltar={() => setTela("diaristaLogin")}
            onConcluir={finalizarCadastroDiarista}
            corBotao={{ background: `linear-gradient(120deg, ${D_CORAL_LIGHT} 0%, ${D_CORAL} 55%, ${D_CORAL_DEEP} 100%)`, color: "#FFFFFF", boxShadow: "0 4px 14px rgba(201,68,48,0.35)" }}
            corAcento={D_CORAL_DEEP}
            appNome="Diarista de Aluguel"
          />
        )}

        {tela === "confirmacaoPagamentoDiarista" && perfilDiaristaPendente && (
          <ConfirmacaoPagamento perfil={perfilDiaristaPendente} onContinuar={pagamentoConfirmadoDiarista} />
        )}

        {tela === "confirmacaoEmailDiarista" && perfilDiaristaPendente && (
          <ConfirmacaoEmail email={perfilDiaristaPendente.email} onConfirmar={confirmarEmailDiarista} />
        )}

        {tela === "cadastroClienteDiarista" && (
          <CadastroMae
            titulo="Cadastro de cliente"
            onVoltar={() => setTela("diaristaLogin")}
            onConcluir={cadastroClienteDiaristaEnviado}
            corFundo="#FFF6F1"
            corTexto="#5A2420"
            corBotao={{ background: `linear-gradient(120deg, ${D_CORAL_LIGHT} 0%, ${D_CORAL} 55%, ${D_CORAL_DEEP} 100%)`, color: "#FFFFFF", boxShadow: "0 4px 14px rgba(201,68,48,0.35)" }}
          />
        )}

        {tela === "confirmacaoEmailClienteDiarista" && dadosClientePendente && (
          <ConfirmacaoEmail email={dadosClientePendente.email} onConfirmar={confirmarEmailClienteDiarista} />
        )}

        {tela === "diaristaApp" && (
          <>
            <div style={{ background: "#5A2420", padding: "16px 18px 16px", borderBottom: `1px solid ${D_CORAL_DEEP}` }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 9 }}>
                  <LogoBrilho width={30} style={{ borderRadius: 6 }} src={LOGO_DIARISTA_B64} alt="Diarista de Aluguel" />
                  <span style={{ fontFamily: "Fraunces, serif", fontSize: 16, color: "#FFF6F1", fontWeight: 600, letterSpacing: 0.2 }}>
                    Diarista de Aluguel
                  </span>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <button onClick={() => setVerNotificacoes(true)} style={{
                    position: "relative", display: "flex", alignItems: "center", justifyContent: "center", width: 28, height: 28,
                    borderRadius: "50%", background: "rgba(226,122,109,0.22)", border: `1px solid ${D_CORAL}`, cursor: "pointer",
                  }} title="Notificações">
                    <Bell size={13} color={D_CORAL} />
                    {notificacoes.some((n) => !n.lida) && (
                      <span style={{ position: "absolute", top: 3, right: 4, width: 6, height: 6, borderRadius: "50%", background: "#FFD166" }} />
                    )}
                  </button>
                  {modoDiarista === "cliente" && (
                    <button onClick={() => setVerPerfilCliente(true)} style={{
                      display: "flex", alignItems: "center", justifyContent: "center", width: 28, height: 28,
                      borderRadius: "50%", background: "rgba(226,122,109,0.22)", border: `1px solid ${D_CORAL}`, cursor: "pointer",
                    }} title="Meu perfil">
                      <User size={13} color={D_CORAL} />
                    </button>
                  )}
                  <button onClick={() => { setModoDiarista(modoDiarista === "cliente" ? "diarista" : "cliente"); setSelecionadaDiarista(null); setVerPerfilCliente(false); }} style={{
                    display: "flex", alignItems: "center", gap: 5, background: "rgba(226,122,109,0.22)",
                    border: `1px solid ${D_CORAL}`, borderRadius: 20, padding: "6px 11px", cursor: "pointer",
                  }}>
                    <ArrowLeftRight size={12} color={D_CORAL} />
                    <span style={{ fontSize: 10.5, color: "#FFF6F1", fontFamily: "Manrope, sans-serif" }}>
                      {modoDiarista === "cliente" ? "Sou cliente" : "Sou diarista"}
                    </span>
                  </button>
                </div>
              </div>
              <p style={{ fontSize: 11.5, color: "#E4C3BC", fontFamily: "Manrope, sans-serif", marginTop: 5 }}>
                {modoDiarista === "cliente" ? "Encontre uma diarista de confiança perto de você" : "Gerencie seu perfil e sua agenda"}
              </p>
            </div>
            <div style={{ flex: 1, overflowY: "hidden", minHeight: 0 }}>
              {verHistorico === "cliente" ? (
                <HistoricoScreen
                  contratacoes={contratacoes}
                  papel="cliente"
                  onVoltar={() => setVerHistorico(null)}
                  onAvaliar={abrirAvaliacao}
                  onConcluir={concluirContratacao}
                  onCancelar={cancelarContratacao}
                  onAvisoContato={notificarContatosConfianca}
                  corDestaque={D_CORAL}
                  corHeader="#5A2420"
                  corTexto="#FFF6F1"
                  meuContato={meuPerfilCliente}
                />
              ) : verHistorico === "prestadorDiarista" ? (
                <HistoricoScreen
                  contratacoes={contratacoes.filter((c) => c.prestadorTipo === "diarista" && c.prestadorId === meuPerfilDiarista.id)}
                  papel="prestadorDiarista"
                  onVoltar={() => setVerHistorico(null)}
                  onAceitar={aceitarContratacao}
                  onRecusar={recusarContratacao}
                  onConcluir={concluirContratacao}
                  onCheckin={registrarCheckin}
                  onCheckout={registrarCheckout}
                  onAvisoContato={notificarContatosConfianca}
                  corDestaque={D_CORAL}
                  corHeader="#5A2420"
                  corTexto="#FFF6F1"
                  meuContato={meuPerfilDiarista}
                />
              ) : verBloqueados ? (
                <BloqueadosScreen
                  bloqueados={perfisBloqueados}
                  onVoltar={() => setVerBloqueados(false)}
                  onDesbloquear={desbloquearPerfil}
                  corDestaque={D_CORAL}
                  corHeader="#5A2420"
                  corTexto="#FFF6F1"
                />
              ) : verPerfilCliente ? (
                <PerfilMae
                  perfil={meuPerfilCliente}
                  onVoltar={() => setVerPerfilCliente(false)}
                  onSalvar={atualizarPerfilCliente}
                  onAtualizarFoto={atualizarFotoPerfilCliente}
                  onVerContratacoes={() => setVerHistorico("cliente")}
                  onVerBloqueados={() => setVerBloqueados(true)}
                  totalBloqueados={perfisBloqueados.length}
                  corDestaque={D_CORAL}
                  corHeader="#5A2420"
                  corTexto="#FFF6F1"
                  rotulo="Cliente na Diarista de Aluguel"
                  appNome="diarista"
                />
              ) : selecionadaDiarista ? (
                <DiaristaDetail
                  diarista={selecionadaDiarista}
                  onBack={() => setSelecionadaDiarista(null)}
                  editable={false}
                  onAgendar={agendarServico}
                  avaliacoesExtras={avaliacoesExtras}
                  onDenunciar={(perfil, motivo, detalhes) => enviarDenuncia(perfil, "diarista", motivo, detalhes)}
                  onBloquear={(perfil) => bloquearPerfil(perfil, "diarista")}
                  meuContato={meuPerfilCliente}
                  onConfigurarContato={() => { setSelecionadaDiarista(null); setVerPerfilCliente(true); }}
                  onAvisoSilencioso={notificarContatosConfianca}
                />
              ) : modoDiarista === "cliente" ? (
                <DiaristaSearchView onSelect={setSelecionadaDiarista} bloqueados={idsBloqueadosDiarista} />
              ) : (
                <DiaristaDetail
                  diarista={meuPerfilDiarista}
                  onBack={() => setTela("hub")}
                  editable={true}
                  onAtualizarFoto={atualizarFotoPerfilDiarista}
                  onAdicionarTrabalho={adicionarTrabalhoDiarista}
                  onSalvarPerfil={atualizarPerfilDiarista}
                  avaliacoesExtras={avaliacoesExtras}
                  onVerAgenda={() => setVerHistorico("prestadorDiarista")}
                  pendentesCount={pendentesDiarista}
                />
              )}
            </div>
          </>
        )}

        {tela === "login" && (
          <LoginScreen tipo={tipoLogin} setTipo={setTipoLogin} onLogin={fazerLogin} onCadastro={irParaCadastro} onVoltar={() => setTela("hub")} />
        )}

        {tela === "cadastroMae" && (
          <CadastroMae onVoltar={() => setTela("login")} onConcluir={cadastroMaeEnviado} />
        )}

        {tela === "confirmacaoEmailMae" && dadosMaePendente && (
          <ConfirmacaoEmail email={dadosMaePendente.email} onConfirmar={confirmarEmailMae} />
        )}

        {tela === "cadastroBaba" && (
          <CadastroBaba onVoltar={() => setTela("login")} onConcluir={finalizarCadastroBaba} />
        )}

        {tela === "confirmacaoPagamento" && perfilPendente && (
          <ConfirmacaoPagamento perfil={perfilPendente} onContinuar={pagamentoConfirmado} />
        )}

        {tela === "confirmacaoEmailBaba" && perfilPendente && (
          <ConfirmacaoEmail email={perfilPendente.email} onConfirmar={confirmarEmailBaba} />
        )}

        {tela === "app" && !selecionada && !verPerfilMae && !verBloqueados && !verHistorico && (
          <>
            <div style={{ background: INK, padding: "16px 18px 16px", borderBottom: `1px solid ${GOLD_DEEP}` }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 9 }}>
                  <LogoBrilho width={30} style={{ borderRadius: 6 }} />
                  <span style={{ fontFamily: "Fraunces, serif", fontSize: 18, color: PAPER, fontWeight: 600, letterSpacing: 0.2 }}>
                    Babá de Aluguel
                  </span>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <button onClick={() => setVerNotificacoes(true)} style={{
                    position: "relative", display: "flex", alignItems: "center", justifyContent: "center", width: 28, height: 28,
                    borderRadius: "50%", background: "rgba(201,138,86,0.16)", border: `1px solid ${GOLD}`, cursor: "pointer",
                  }} title="Notificações">
                    <Bell size={13} color={GOLD} />
                    {notificacoes.some((n) => !n.lida) && (
                      <span style={{ position: "absolute", top: 3, right: 4, width: 6, height: 6, borderRadius: "50%", background: "#D64545" }} />
                    )}
                  </button>
                  {modo === "mae" && (
                    <button onClick={() => setVerPerfilMae(true)} style={{
                      display: "flex", alignItems: "center", justifyContent: "center", width: 28, height: 28,
                      borderRadius: "50%", background: "rgba(201,138,86,0.16)", border: `1px solid ${GOLD}`, cursor: "pointer",
                    }} title="Meu perfil">
                      <User size={13} color={GOLD} />
                    </button>
                  )}
                  <button onClick={() => { setModo(modo === "mae" ? "baba" : "mae"); setVerPerfilMae(false); }} style={{
                    display: "flex", alignItems: "center", gap: 5, background: "rgba(201,138,86,0.16)",
                    border: `1px solid ${GOLD}`, borderRadius: 20, padding: "6px 11px", cursor: "pointer",
                  }}>
                    <ArrowLeftRight size={12} color={GOLD} />
                    <span style={{ fontSize: 10.5, color: PAPER, fontFamily: "Manrope, sans-serif" }}>
                      {modo === "mae" ? "Sou mãe" : "Sou babá"}
                    </span>
                  </button>
                </div>
              </div>
              <p style={{ fontSize: 11.5, color: "#D8C3A8", fontFamily: "Manrope, sans-serif", marginTop: 5 }}>
                {modo === "mae" ? "Encontre uma babá de confiança perto de você" : "Gerencie seu perfil e sua agenda"}
              </p>
            </div>
            <div style={{ flex: 1, overflowY: modo === "mae" ? "hidden" : "auto", minHeight: 0 }}>
              {modo === "mae" ? (
                <MaeView
                  onSelect={setSelecionada}
                  boosts={boosts}
                  perfilImpulsionado={boosts.destaque?.ativo || boosts.banner?.ativo || boosts.popup?.ativo ? meuPerfilBaba : null}
                  bloqueados={idsBloqueadosBaba}
                />
              ) : (
                <div style={{ padding: 16 }}>
                  <BabaCard baba={meuPerfilBaba} onClick={() => setSelecionada(meuPerfilBaba)} destaque={boosts.destaque?.ativo} />
                  {!meuPerfilBaba.fotoUrl && (
                    <div style={{
                      display: "flex", alignItems: "center", gap: 6, marginTop: 10, justifyContent: "center",
                    }}>
                      <Camera size={12} color={GOLD_DEEP} />
                      <span style={{ fontSize: 11, color: GOLD_DEEP, fontFamily: "Manrope, sans-serif", fontWeight: 700 }}>
                        Não esqueça de adicionar sua foto de perfil
                      </span>
                    </div>
                  )}
                  <p style={{ fontSize: 11.5, color: "#8B6A52", fontFamily: "Manrope, sans-serif", marginTop: 10, textAlign: "center" }}>
                    Toque no seu cartão para ver e editar seu perfil público.
                  </p>

                  <button onClick={() => setTela("impulsionamento")} style={{
                    display: "flex", alignItems: "center", gap: 10, width: "100%", textAlign: "left",
                    background: `linear-gradient(135deg, ${GOLD} 0%, ${GOLD_DEEP} 100%)`, border: "none",
                    borderRadius: 16, padding: "14px 15px", marginTop: 18, cursor: "pointer",
                    boxShadow: "0 4px 14px rgba(156,95,53,0.25)",
                  }}>
                    <div style={{
                      width: 38, height: 38, borderRadius: "50%", background: "rgba(255,255,255,0.35)",
                      display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
                    }}>
                      <Rocket size={17} color="#4A2A12" />
                    </div>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontSize: 13.5, fontWeight: 700, color: "#4A2A12", fontFamily: "Manrope, sans-serif", margin: 0 }}>
                        Impulsionar meu perfil
                      </p>
                      <p style={{ fontSize: 11, color: "#4A2A12", fontFamily: "Manrope, sans-serif", margin: "2px 0 0" }}>
                        Apareça mais para as famílias e receba mais chamadas
                      </p>
                    </div>
                    <ChevronLeft size={16} color="#4A2A12" style={{ transform: "rotate(180deg)" }} />
                  </button>
                </div>
              )}
            </div>
          </>
        )}

        {tela === "impulsionamento" && (
          <TelaImpulsionamento boosts={boosts} onAtivar={ativarImpulsionamento} onVoltar={() => setTela("app")} />
        )}

        {tela === "app" && verHistorico === "cliente" && (
          <HistoricoScreen
            contratacoes={contratacoes}
            papel="cliente"
            onVoltar={() => setVerHistorico(null)}
            onAvaliar={abrirAvaliacao}
            onConcluir={concluirContratacao}
            onCancelar={cancelarContratacao}
            onAvisoContato={notificarContatosConfianca}
            corDestaque={GOLD_DEEP}
            corHeader={INK}
            corTexto={PAPER}
            meuContato={meuPerfilMae}
          />
        )}

        {tela === "app" && verHistorico === "prestadorBaba" && (
          <HistoricoScreen
            contratacoes={contratacoes.filter((c) => c.prestadorTipo === "baba" && c.prestadorId === meuPerfilBaba.id)}
            papel="prestadorBaba"
            onVoltar={() => setVerHistorico(null)}
            onAceitar={aceitarContratacao}
            onRecusar={recusarContratacao}
            onConcluir={concluirContratacao}
            onCheckin={registrarCheckin}
            onCheckout={registrarCheckout}
            onAvisoContato={notificarContatosConfianca}
            corDestaque={GOLD_DEEP}
            corHeader={INK}
            corTexto={PAPER}
            meuContato={meuPerfilBaba}
          />
        )}

        {tela === "app" && !verHistorico && verBloqueados && (
          <BloqueadosScreen
            bloqueados={perfisBloqueados}
            onVoltar={() => setVerBloqueados(false)}
            onDesbloquear={desbloquearPerfil}
            corDestaque={GOLD_DEEP}
            corHeader={INK}
            corTexto={PAPER}
          />
        )}

        {tela === "app" && !verHistorico && !verBloqueados && verPerfilMae && (
          <PerfilMae
            perfil={meuPerfilMae}
            onVoltar={() => setVerPerfilMae(false)}
            onSalvar={atualizarPerfilMae}
            onAtualizarFoto={atualizarFotoPerfilMae}
            onVerContratacoes={() => setVerHistorico("cliente")}
            onVerBloqueados={() => setVerBloqueados(true)}
            totalBloqueados={perfisBloqueados.length}
          />
        )}

        {tela === "app" && !verHistorico && !verBloqueados && selecionada && (
          <BabaDetail
            baba={selecionada}
            onBack={() => setSelecionada(null)}
            editable={modo === "baba"}
            onAtualizarFoto={modo === "baba" ? atualizarFotoPerfil : undefined}
            onSalvarPerfil={modo === "baba" ? atualizarPerfilBaba : undefined}
            onAgendar={agendarServico}
            avaliacoesExtras={avaliacoesExtras}
            onVerAgenda={modo === "baba" ? () => setVerHistorico("prestadorBaba") : undefined}
            pendentesCount={pendentesBaba}
            onDenunciar={modo === "mae" ? (perfil, motivo, detalhes) => enviarDenuncia(perfil, "baba", motivo, detalhes) : undefined}
            onBloquear={modo === "mae" ? (perfil) => bloquearPerfil(perfil, "baba") : undefined}
            meuContato={meuPerfilMae}
            onConfigurarContato={() => { setSelecionada(null); setVerPerfilMae(true); }}
            onAvisoSilencioso={notificarContatosConfianca}
          />
        )}
      </div>

      {avaliando && (
        <AvaliarModal
          nome={avaliando.prestadorNome}
          corDestaque={avaliando.prestadorTipo === "diarista" ? D_CORAL_DEEP : GOLD_DEEP}
          onClose={() => setAvaliando(null)}
          onEnviar={enviarAvaliacao}
        />
      )}

      {verNotificacoes && (
        <NotificacoesScreen
          notificacoes={notificacoes}
          onVoltar={() => setVerNotificacoes(false)}
          onLerTodas={() => setNotificacoes((n) => n.map((x) => ({ ...x, lida: true })))}
        />
      )}
    </div>
  );
}
